        if let Some(v) = other.is_zip_archive { self.is_zip_archive = Some(v); }
        if let Some(v) = other.is_audio { self.is_audio = Some(v); }
        if let Some(v) = other.is_book { self.is_book = Some(v); }
        if let Some(v) = other.is_doc { self.is_doc = Some(v); }
        if let Some(v) = other.is_font { self.is_font = Some(v); }
        if let Some(v) = other.is_image { self.is_image = Some(v); }
        if let Some(v) = other.is_source { self.is_source = Some(v); }
        if let Some(v) = other.is_video { self.is_video = Some(v); }
    }

    pub fn is_ext_match(&self, ext_without_dot: &str, category: &str) -> bool {
        let ext_with_dot = if ext_without_dot.starts_with('.') {
            ext_without_dot.to_lowercase()
        } else {
            format!(".{}", ext_without_dot.to_lowercase())
        };

        let vec_opt = match category {
            "archive" => self.is_archive.as_ref(),
            "zip_archive" => self.is_zip_archive.as_ref(),
            "audio" => self.is_audio.as_ref(),
            "book" => self.is_book.as_ref(),
            "doc" => self.is_doc.as_ref(),
            "font" => self.is_font.as_ref(),
            "image" => self.is_image.as_ref(),
            "source" => self.is_source.as_ref(),
            "video" => self.is_video.as_ref(),
            _ => None,
        };

        if let Some(vec) = vec_opt {
            vec.iter().any(|e| {
                let e_dot = if e.starts_with('.') { e.to_lowercase() } else { format!(".{}", e.to_lowercase()) };
                e_dot == ext_with_dot
            })
        } else {
            false
        }
    }
}
EOF"}

