{"command":"cat <<'EOF' > src/parser.rs
use crate::ast::*;
use crate::lexer::Token;

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    raw_query: String,
}

impl Parser {
    pub fn new(tokens: Vec<Token>, raw_query: String) -> Self {
        Parser { tokens, pos: 0, raw_query }
    }

    fn peek(&self) -> &Token {
        if self.pos < self.tokens.len() {
            &self.tokens[self.pos]
        } else {
            &Token::Eof
        }
    }

    fn peek_next(&self) -> &Token {
        if self.pos + 1 < self.tokens.len() {
            &self.tokens[self.pos + 1]
        } else {
            &Token::Eof
        }
    }

    fn advance(&mut self) -> &Token {
        if self.pos < self.tokens.len() {
            let t = &self.tokens[self.pos];
            self.pos += 1;
            t
        } else {
            &Token::Eof
        }
    }

    fn check_keyword(&self, kw: &str) -> bool {
        match self.peek() {
            Token::Keyword(k) => k == kw,
            _ => false,
        }
    }

    pub fn parse(&mut self) -> Result<SelectQuery, String> {
        // Optional SELECT
        if self.check_keyword("SELECT") {
            self.advance();
        }

        let fields = self.parse_fields()?;
        if fields.is_empty() {
            return Err("Error parsing fields, no selector found".to_string());
        }

        let mut roots = Vec::new();
        if self.check_keyword("FROM") {
            self.advance();
            roots = self.parse_roots()?;
        }
        if roots.is_empty() {
            roots.push(SearchRoot::default());
        }

        let mut where_clause = None;
        if self.check_keyword("WHERE") {
            self.advance();
            where_clause = Some(self.parse_expr()?);
        }

        let mut group_by = Vec::new();
        if self.check_keyword("GROUP") {
            self.advance();
            if self.check_keyword("BY") {
                self.advance();
            }
            group_by = self.parse_expr_list()?;
        }

        let mut order_by = Vec::new();
        if self.check_keyword("ORDER") {
            self.advance();
            if self.check_keyword("BY") {
                self.advance();
            }
            order_by = self.parse_order_by()?;
        }

        let mut limit = None;
        if self.check_keyword("LIMIT") {
            self.advance();
            match self.peek() {
                Token::Integer(n) => {
                    limit = Some(*n as usize);
                    self.advance();
                }
                _ => return Err("could not parse tokens at the end of the query".to_string()),
            }
        }

        let mut offset = None;
        if self.check_keyword("OFFSET") {
            self.advance();
            match self.peek() {
                Token::Integer(n) => {
                    offset = Some(*n as usize);
                    self.advance();
                }
                _ => return Err("could not parse tokens at the end of the query".to_string()),
            }
        }

        let mut into_format = OutputFormat::Tabs;
        if self.check_keyword("INTO") {
            self.advance();
            let fmt_str = match self.advance() {
                Token::Identifier(s) | Token::Keyword(s) | Token::StringLiteral(s) => s.to_lowercase(),
                _ => return Err("Unknown output format".to_string()),
            };
            into_format = match fmt_str.as_str() {
                "tabs" => OutputFormat::Tabs,
                "lines" => OutputFormat::Lines,
                "list" => OutputFormat::List,
                "csv" => OutputFormat::Csv,
                "json" => OutputFormat::Json,
                "html" => OutputFormat::Html,
                _ => return Err("Unknown output format".to_string()),
            };
        }

        if !matches!(self.peek(), Token::Eof) {
            return Err("could not parse tokens at the end of the query".to_string());
        }

        Ok(SelectQuery {
            raw_query: self.raw_query.clone(),
            fields,
            roots,
            where_clause,
            group_by,
            order_by,
            limit,
            offset,
            into_format,
        })
    }

    fn parse_fields(&mut self) -> Result<Vec<Expr>, String> {
        let mut exprs = Vec::new();
        while !matches!(self.peek(), Token::Eof) && !self.is_clause_keyword() {
            let expr = self.parse_expr()?;
            exprs.push(expr);
            if matches!(self.peek(), Token::Comma) {
                self.advance();
            }
        }
        Ok(exprs)
    }

    fn parse_expr_list(&mut self) -> Result<Vec<Expr>, String> {
        let mut exprs = Vec::new();
        while !matches!(self.peek(), Token::Eof) && !self.is_clause_keyword() {
            let expr = self.parse_expr()?;
            exprs.push(expr);
            if matches!(self.peek(), Token::Comma) {
                self.advance();
            }
        }
        Ok(exprs)
    }

    fn parse_order_by(&mut self) -> Result<Vec<OrderByClause>, String> {
        let mut clauses = Vec::new();
        while !matches!(self.peek(), Token::Eof) && !self.is_clause_keyword() {
            let expr = self.parse_expr()?;
            let mut desc = false;
            if self.check_keyword("DESC") {
                desc = true;
                self.advance();
            } else if self.check_keyword("ASC") {
                self.advance();
            }
            clauses.push(OrderByClause { expr, desc });
            if matches!(self.peek(), Token::Comma) {
                self.advance();
            }
        }
        Ok(clauses)
    }

    fn parse_roots(&mut self) -> Result<Vec<SearchRoot>, String> {
        let mut roots = Vec::new();
        while !matches!(self.peek(), Token::Eof) && !self.is_clause_keyword() {
            let path = match self.advance() {
                Token::Identifier(s) | Token::StringLiteral(s) | Token::Keyword(s) => s.clone(),
                _ => return Err("Error parsing search root".to_string()),
            };

            let mut root = SearchRoot {
                path,
                ..Default::default()
            };

            // Parse root options
            while !matches!(self.peek(), Token::Eof | Token::Comma) && !self.is_clause_keyword() {
                if self.check_keyword("MINDEPTH") {
                    self.advance();
                    if let Token::Integer(n) = self.advance() {
                        root.min_depth = Some(*n as usize);
                    }
                } else if self.check_keyword("MAXDEPTH") || self.check_keyword("DEPTH") {
                    self.advance();
                    if let Token::Integer(n) = self.advance() {
                        root.max_depth = Some(*n as usize);
                    }
                } else if self.check_keyword("ARCHIVES") || self.check_keyword("ARC") {
                    self.advance();
                    root.archives = true;
                } else if self.check_keyword("SYMLINKS") || self.check_keyword("SYM") {
                    self.advance();
                    root.symlinks = true;
                } else if self.check_keyword("GITIGNORE") || self.check_keyword("GIT") {
                    self.advance();
                    root.gitignore = Some(true);
                } else if self.check_keyword("NOGITIGNORE") || self.check_keyword("NOGIT") {
                    self.advance();
                    root.gitignore = Some(false);
                } else if self.check_keyword("HGIGNORE") || self.check_keyword("HG") {
                    self.advance();
                    root.hgignore = Some(true);
                } else if self.check_keyword("NOHGIGNORE") || self.check_keyword("NOHG") {
                    self.advance();
                    root.hgignore = Some(false);
                } else if self.check_keyword("DOCKERIGNORE") || self.check_keyword("DOCKER") {
                    self.advance();
                    root.dockerignore = Some(true);
                } else if self.check_keyword("NODOCKERIGNORE") || self.check_keyword("NODOCKER") {
                    self.advance();
                    root.dockerignore = Some(false);
                } else if self.check_keyword("DFS") {
                    self.advance();
                    root.dfs = true;
                } else if self.check_keyword("BFS") {
                    self.advance();
                    root.dfs = false;
                } else if self.check_keyword("REGEXP") || self.check_keyword("RX") {
                    self.advance();
                    root.is_regexp = true;
                } else if self.check_keyword("AS") {
                    self.advance();
                    match self.advance() {
                        Token::Identifier(s) | Token::Keyword(s) => root.alias = Some(s.clone()),
                        _ => return Err("Expecting root alias".to_string()),
                    }
                } else {
                    break;
                }
            }

            roots.push(root);
            if matches!(self.peek(), Token::Comma) {
                self.advance();
            }
        }
        Ok(roots)
    }

    fn is_clause_keyword(&self) -> bool {
        match self.peek() {
            Token::Keyword(k) => matches!(k.as_str(), "FROM" | "WHERE" | "GROUP" | "ORDER" | "LIMIT" | "OFFSET" | "INTO"),
            _ => false,
        }
    }

    fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_and()?;
        while self.check_keyword("OR") {
            self.advance();
            let right = self.parse_and()?;
            left = Expr::BinaryOp(Box::new(left), Op::Or, Box::new(right));
        }
        Ok(left)
    }

    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_not()?;
        while self.check_keyword("AND") {
            self.advance();
            let right = self.parse_not()?;
            left = Expr::BinaryOp(Box::new(left), Op::And, Box::new(right));
        }
        Ok(left)
    }

    fn parse_not(&mut self) -> Result<Expr, String> {
        if self.check_keyword("NOT") {
            self.advance();
            let expr = self.parse_comparison()?;
            Ok(Expr::UnaryOp(Op::Not, Box::new(expr)))
        } else {
            self.parse_comparison()
        }
    }

    fn parse_comparison(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_addition()?;

        if self.check_keyword("BETWEEN") {
            self.advance();
            let low = self.parse_addition()?;
            if self.check_keyword("AND") {
                self.advance();
            }
            let high = self.parse_addition()?;
            return Ok(Expr::Between(Box::new(left), Box::new(low), Box::new(high)));
        }

        if self.check_keyword("IN") {
            self.advance();
            if matches!(self.peek(), Token::LParen) {
                self.advance();
                // Check if subquery (SELECT ...)
                if self.check_keyword("SELECT") || self.check_keyword("NAME") || self.check_keyword("PATH") || self.check_keyword("SIZE") {
                    let subparser_tokens = self.collect_until_rparen()?;
                    let mut subparser = Parser::new(subparser_tokens, "".to_string());
                    let subquery = subparser.parse()?;
                    return Ok(Expr::InSubquery(Box::new(left), Box::new(subquery), false));
                } else {
                    let mut list = Vec::new();
                    while !matches!(self.peek(), Token::RParen | Token::Eof) {
                        list.push(self.parse_expr()?);
                        if matches!(self.peek(), Token::Comma) {
                            self.advance();
                        }
                    }
                    if matches!(self.peek(), Token::RParen) {
                        self.advance();
                    }
                    return Ok(Expr::InList(Box::new(left), list));
                }
            }
        }

        if self.check_keyword("NOT") {
            if matches!(self.peek_next(), Token::Keyword(ref k) if k == "IN") {
                self.advance(); // NOT
                self.advance(); // IN
                if matches!(self.peek(), Token::LParen) {
                    self.advance();
                    if self.check_keyword("SELECT") || self.check_keyword("NAME") || self.check_keyword("PATH") || self.check_keyword("SIZE") {
                        let subparser_tokens = self.collect_until_rparen()?;
                        let mut subparser = Parser::new(subparser_tokens, "".to_string());
                        let subquery = subparser.parse()?;
                        return Ok(Expr::InSubquery(Box::new(left), Box::new(subquery), true));
                    } else {
                        let mut list = Vec::new();
                        while !matches!(self.peek(), Token::RParen | Token::Eof) {
                            list.push(self.parse_expr()?);
                            if matches!(self.peek(), Token::Comma) {
                                self.advance();
                            }
                        }
                        if matches!(self.peek(), Token::RParen) {
                            self.advance();
                        }
                        let in_expr = Expr::InList(Box::new(left), list);
                        return Ok(Expr::UnaryOp(Op::Not, Box::new(in_expr)));
                    }
                }
            }
        }

        if self.check_keyword("EXISTS") {
            self.advance();
            if matches!(self.peek(), Token::LParen) {
                self.advance();
                let subparser_tokens = self.collect_until_rparen()?;
                let mut subparser = Parser::new(subparser_tokens, "".to_string());
                let subquery = subparser.parse()?;
                return Ok(Expr::ExistsSubquery(Box::new(subquery), false));
            }
        }

        let op = match self.peek() {
            Token::Operator(op_str) => {
                let op = match op_str.as_str() {
                    "=" | "==" => Op::Eq,
                    "===" => Op::ExactEq,
                    "!=" | "<>" => Op::Ne,
                    "!==" => Op::ExactNe,
                    "<" => Op::Lt,
                    "<=" => Op::Lte,
                    ">" => Op::Gt,
                    ">=" => Op::Gte,
                    "=~" | "~=" => Op::RegexMatch,
                    "!=~" | "!~=" => Op::RegexNoMatch,
                    "LIKE" => Op::Like,
                    "NOTLIKE" => Op::NotLike,
                    _ => return Ok(left),
                };
                self.advance();
                Some(op)
            }
            _ => None,
        };

        if let Some(op) = op {
            let right = self.parse_addition()?;
            Ok(Expr::BinaryOp(Box::new(left), op, Box::new(right)))
        } else {
            Ok(left)
        }
    }

    fn collect_until_rparen(&mut self) -> Result<Vec<Token>, String> {
        let mut depth = 1;
        let mut tokens = Vec::new();
        while !matches!(self.peek(), Token::Eof) {
            let t = self.advance().clone();
            match t {
                Token::LParen => depth += 1,
                Token::RParen => {
                    depth -= 1;
                    if depth == 0 {
                        tokens.push(Token::Eof);
                        return Ok(tokens);
                    }
                }
                _ => {}
            }
            tokens.push(t);
        }
        Err("Unmatched parenthesis".to_string())
    }

    fn parse_addition(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_multiplication()?;
        while let Token::Operator(op_str) = self.peek() {
            let op = match op_str.as_str() {
                "+" => Op::Add,
                "-" => Op::Sub,
                _ => break,
            };
            self.advance();
            let right = self.parse_multiplication()?;
            left = Expr::BinaryOp(Box::new(left), op, Box::new(right));
        }
        Ok(left)
    }

    fn parse_multiplication(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_primary()?;
        while let Token::Operator(op_str) = self.peek() {
            let op = match op_str.as_str() {
                "*" => Op::Mul,
                "/" => Op::Div,
                "%" => Op::Mod,
                _ => break,
            };
            self.advance();
            let right = self.parse_primary()?;
            left = Expr::BinaryOp(Box::new(left), op, Box::new(right));
        }
        Ok(left)
    }

    fn parse_primary(&mut self) -> Result<Expr, String> {
        match self.peek().clone() {
            Token::StringLiteral(s) => {
                self.advance();
                Ok(Expr::Literal(Value::String(s)))
            }
            Token::Integer(n) => {
                self.advance();
                Ok(Expr::Literal(Value::Integer(n)))
            }
            Token::Float(f) => {
                self.advance();
                Ok(Expr::Literal(Value::Float(f)))
            }
            Token::SizeLiteral(sz) => {
                self.advance();
                Ok(Expr::Literal(Value::Integer(sz as i64)))
            }
            Token::Keyword(kw) => {
                if kw == "TRUE" {
                    self.advance();
                    Ok(Expr::Literal(Value::Bool(true)))
                } else if kw == "FALSE" {
                    self.advance();
                    Ok(Expr::Literal(Value::Bool(false)))
                } else if kw == "NULL" {
                    self.advance();
                    Ok(Expr::Literal(Value::Null))
                } else {
                    self.parse_identifier_or_fn()
                }
            }
            Token::Identifier(_) => self.parse_identifier_or_fn(),
            Token::LParen | Token::LBrace => {
                let closing_bracket = if matches!(self.peek(), Token::LParen) { Token::RParen } else { Token::RBrace };
                self.advance();
                let expr = self.parse_expr()?;
                if self.peek() == &closing_bracket {
                    self.advance();
                    Ok(expr)
                } else {
                    Err("Unmatched parenthesis".to_string())
                }
            }
            _ => Err("Error parsing expression, expecting string".to_string()),
        }
    }

    fn parse_identifier_or_fn(&mut self) -> Result<Expr, String> {
        let name = match self.advance() {
            Token::Identifier(s) | Token::Keyword(s) => s.clone(),
            _ => return Err("Error parsing expression, expecting string".to_string()),
        };

        // Check if function call e.g. NAME(...) or NAME{...}
        if matches!(self.peek(), Token::LParen | Token::LBrace) {
            let closing_bracket = if matches!(self.peek(), Token::LParen) { Token::RParen } else { Token::RBrace };
            self.advance();
            let mut args = Vec::new();
            while self.peek() != &closing_bracket && !matches!(self.peek(), Token::Eof) {
                if matches!(self.peek(), Token::Operator(op) if op == "*") {
                    self.advance();
                    args.push(Expr::Column("*".to_string()));
                } else {
                    args.push(Expr::parse_expr_internal(self)?);
                }
                if matches!(self.peek(), Token::Comma) {
                    self.advance();
                }
            }
            if self.peek() == &closing_bracket {
                self.advance();
            } else {
                return Err("Unmatched parenthesis".to_string());
            }
            Ok(Expr::FunctionCall(name, args))
        } else {
            Ok(Expr::Column(name))
        }
    }
}

impl Expr {
    fn parse_expr_internal(parser: &mut Parser) -> Result<Expr, String> {
        parser.parse_expr()
    }
}
EOF"}

