                    args.push(Expr::parse_expr_internal(self)?);
                }
                if matches!(self.peek(), Token::Comma) {
                    self.advance();
                }
            }
            if self.peek() == &closing_bracket {
                self.advance();
            } else {
                return Err("Unmatched parenthesis".to_string());
            }
            Ok(Expr::FunctionCall(name, args))
        } else {
            Ok(Expr::Column(name))
        }
    }
}

impl Expr {
    fn parse_expr_internal(parser: &mut Parser) -> Result<Expr, String> {
        parser.parse_expr()
    }
}
