{"command":"cat <<'EOF' > src/formatter.rs
use std::collections::BTreeMap;
use serde_json::Value as JsonValue;
use std::os::unix::io::AsRawFd;

use crate::ast::*;
use crate::config::Config;
use crate::file_info::FileInfo;

pub fn is_stdout_tty() -> bool {
    unsafe { libc::isatty(libc::STDOUT_FILENO) == 1 }
}

pub fn is_stderr_tty() -> bool {
    unsafe { libc::isatty(libc::STDERR_FILENO) == 1 }
}

pub fn colorize_text(text: &str, file: Option<&FileInfo>, config: &Config, enable_color: bool) -> String {
    if !enable_color {
        return text.to_string();
    }
    if let Some(fi) = file {
        let ext = fi.ext();
        if fi.is_dir() {
            format!("\x1b[1;34m{}\x1b[0m", text) // Bold Blue
        } else if fi.is_symlink() {
            format!("\x1b[1;36m{}\x1b[0m", text) // Bold Cyan
        } else if config.is_ext_match(&ext, "archive") {
            format!("\x1b[1;31m{}\x1b[0m", text) // Bold Red
        } else if config.is_ext_match(&ext, "image") || config.is_ext_match(&ext, "video") {
            format!("\x1b[1;35m{}\x1b[0m", text) // Bold Magenta
        } else if (fi.mode_bits() & 0o111) != 0 {
            format!("\x1b[1;32m{}\x1b[0m", text) // Bold Green
        } else {
            text.to_string()
        }
    } else {
        text.to_string()
    }
}

pub fn expr_to_json_key(expr: &Expr) -> String {
    match expr {
        Expr::Column(name) => {
            let n = name.to_lowercase();
            match n.as_str() {
                "name" => "Name".to_string(),
                "fname" | "filename" => "Filename".to_string(),
                "ext" | "extension" => "Extension".to_string(),
                "path" => "Path".to_string(),
                "abspath" => "AbsPath".to_string(),
                "dir" | "dirname" | "directory" => "Directory".to_string(),
                "absdir" => "AbsDir".to_string(),
                "size" => "Size".to_string(),
                "fsize" | "hsize" => "FormattedSize".to_string(),
                "created" => "Created".to_string(),
                "accessed" => "Accessed".to_string(),
                "modified" => "Modified".to_string(),
                "is_dir" => "IsDir".to_string(),
                "is_file" => "IsFile".to_string(),
                "is_symlink" => "IsSymlink".to_string(),
                "mode" => "Mode".to_string(),
                "user" => "User".to_string(),
                "group" => "Group".to_string(),
                _ => name.clone(),
            }
        }
        Expr::FunctionCall(name, args) => {
            let fn_name = match name.to_uppercase().as_str() {
                "LOWER" | "LOWERCASE" => "Lower",
                "UPPER" | "UPPERCASE" => "Upper",
                "LENGTH" | "LEN" => "Length",
                _ => name.as_str(),
            };
            if !args.is_empty() {
                let inner = expr_to_json_key(&args[0]);
                format!("{}({})", fn_name, inner)
            } else {
                format!("{}()", fn_name)
            }
        }
        Expr::BinaryOp(left, op, right) => {
            let l = expr_to_json_key(left);
            let r = expr_to_json_key(right);
            let op_str = match op {
                Op::Add => "add",
                Op::Sub => "sub",
                Op::Mul => "mul",
                Op::Div => "div",
                _ => "op",
            };
            format!("{} {} {}", l, op_str, r)
        }
        _ => "field".to_string(),
    }
}

pub struct FormatRow {
    pub values: Vec<Value>,
    pub file: Option<FileInfo>,
}

pub fn format_output(
    query: &SelectQuery,
    rows: &[FormatRow],
    config: &Config,
    enable_color: bool,
) -> String {
    match query.into_format {
        OutputFormat::Tabs => {
            let mut out = String::new();
            for row in rows {
                let line_parts: Vec<String> = row.values.iter().enumerate().map(|(idx, val)| {
                    let text = val.to_string_repr();
                    if idx == 0 {
                        colorize_text(&text, row.file.as_ref(), config, enable_color)
                    } else {
                        text
                    }
                }).collect();
                out.push_str(&line_parts.join("\t"));
                out.push('\n');
            }
            out
        }
        OutputFormat::Lines => {
            let mut out = String::new();
            for row in rows {
                for (idx, val) in row.values.iter().enumerate() {
                    let text = val.to_string_repr();
                    if idx == 0 {
                        out.push_str(&colorize_text(&text, row.file.as_ref(), config, enable_color));
                    } else {
                        out.push_str(&text);
                    }
                    out.push('\n');
                }
            }
            out
        }
        OutputFormat::List => {
            let mut out = String::new();
            for row in rows {
                for val in &row.values {
                    out.push_str(&val.to_string_repr());
                    out.push('\0');
                }
            }
            out
        }
        OutputFormat::Csv => {
            let mut out = String::new();
            for row in rows {
                let line_parts: Vec<String> = row.values.iter().map(|val| {
                    let s = val.to_string_repr();
                    if s.contains(',') || s.contains('"') || s.contains('\n') {
                        format!("\"{}\"", s.replace('"', "\"\""))
                    } else {
                        s
                    }
                }).collect();
                out.push_str(&line_parts.join(","));
                out.push('\n');
            }
            out
        }
        OutputFormat::Json => {
            let field_keys: Vec<String> = query.fields.iter().map(expr_to_json_key).collect();
            let mut json_arr = Vec::new();

            for row in rows {
                let mut map = BTreeMap::new();
                for (idx, val) in row.values.iter().enumerate() {
                    let key = if idx < field_keys.len() { &field_keys[idx] } else { "Value" };
                    map.insert(key.clone(), JsonValue::String(val.to_string_repr()));
                }
                json_arr.push(map);
            }

            serde_json::to_string(&json_arr).unwrap_or_else(|_| "[]".to_string())
        }
        OutputFormat::Html => {
            let mut out = String::new();
            let raw_q = &query.raw_query;
            let col_count = query.fields.len().max(1);

            out.push_str(&format!("<html><head><title>{}</title></head><body><table><tr><th colspan=\"{}\">{}</th></tr>", raw_q, col_count, raw_q));
            for row in rows {
                out.push_str("<tr>");
                for val in &row.values {
                    out.push_str(&format!("<td>{}</td>", val.to_string_repr()));
                }
                out.push_str("</tr>");
            }
            out.push_str("</table></body></html>");
            out
        }
    }
}
EOF"}

