                        format!("\"{}\"", s.replace('"', "\"\""))
                    } else {
                        s
                    }
                }).collect();
                out.push_str(&line_parts.join(","));
                out.push('\n');
            }
            out
        }
        OutputFormat::Json => {
            let field_keys: Vec<String> = query.fields.iter().map(expr_to_json_key).collect();
            let mut json_arr = Vec::new();

            for row in rows {
                let mut map = BTreeMap::new();
                for (idx, val) in row.values.iter().enumerate() {
                    let key = if idx < field_keys.len() { &field_keys[idx] } else { "Value" };
                    map.insert(key.clone(), JsonValue::String(val.to_string_repr()));
                }
                json_arr.push(map);
            }

            serde_json::to_string(&json_arr).unwrap_or_else(|_| "[]".to_string())
        }
        OutputFormat::Html => {
            let mut out = String::new();
            let raw_q = &query.raw_query;
            let col_count = query.fields.len().max(1);

            out.push_str(&format!("<html><head><title>{}</title></head><body><table><tr><th colspan=\"{}\">{}</th></tr>", raw_q, col_count, raw_q));
            for row in rows {
                out.push_str("<tr>");
                for val in &row.values {
                    out.push_str(&format!("<td>{}</td>", val.to_string_repr()));
                }
                out.push_str("</tr>");
            }
            out.push_str("</table></body></html>");
            out
        }
    }
}
