actions.command:
cat <<'EOF' > src/cli.rs
use std::collections::HashMap;
use std::env;
use std::process::exit;

use crate::ast::*;
use crate::config::Config;
use crate::eval::{eval_binary_op, eval_expr, EvalContext};
use crate::file_info::FileInfo;
use crate::formatter::{colorize_text, format_output, is_stderr_tty, is_stdout_tty, FormatRow};
use crate::interactive::run_interactive_mode;
use crate::lexer::Lexer;
use crate::parser::Parser;
use crate::traversal::traverse_root;

const HELP_TEXT: &str = include_str!("help_text.txt");

pub fn print_version(enable_color: bool) {
    if enable_color {
        println!("fselect \x1b[33m0.10.0\x1b[0m");
        println!("Find files with SQL-like queries.");
        println!("\x1b[4;36mhttps://github.com/jhspetersson/fselect\x1b[0m\n");
        println!("Usage: fselect [ARGS] COLUMN[, COLUMN...] [from PATH[, PATH...]] [where EXPR] [group by COLUMN, ...] [order by COLUMN (asc|desc), ...] [limit N] [offset N] [into FORMAT]");
    } else {
        println!("fselect 0.10.0");
        println!("Find files with SQL-like queries.");
        println!("https://github.com/jhspetersson/fselect\n");
        println!("Usage: fselect [ARGS] COLUMN[, COLUMN...] [from PATH[, PATH...]] [where EXPR] [group by COLUMN, ...] [order by COLUMN (asc|desc), ...] [limit N] [offset N] [into FORMAT]");
    }
}

pub fn print_no_args_help(enable_color: bool) {
    print_version(enable_color);
    println!("\nFor more detailed instructions please refer to the URL above or run fselect --help");
}

pub fn print_help_text(enable_color: bool) {
    if enable_color {
        // Colorize header
        println!("fselect \x1b[33m0.10.0\x1b[0m");
        println!("Find files with SQL-like queries.");
        println!("\x1b[4;36mhttps://github.com/jhspetersson/fselect\x1b[0m\n");
