pub fn run_cli() {
    let args: Vec<String> = env::args().collect();

    // Check no args
    if args.len() == 1 {
        let enable_color = env::var("NO_COLOR").is_err() && is_stdout_tty();
        print_no_args_help(enable_color);
        exit(0);
    }

    // Check single flag options
    let first_arg = args[1].as_str();
    if args.len() == 2 {
        if matches!(first_arg, "-h" | "--help" | "/?" | "/h") {
            let enable_color = env::var("NO_COLOR").is_err() && is_stdout_tty();
            print_help_text(enable_color);
            exit(0);
        }
        if matches!(first_arg, "-v" | "-V" | "--version") {
            let enable_color = env::var("NO_COLOR").is_err() && is_stdout_tty();
            print_version(enable_color);
            exit(0);
        }
    }

    // Parse options
    let mut show_errors = true;
    let mut force_no_color = false;
    let mut us_dates = false;
    let mut custom_config_path: Option<String> = None;
    let mut interactive = false;
    let mut query_args = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = args[i].as_str();
        match arg {
            "-i" | "--interactive" | "/i" => {
                interactive = true;
            }
            "--nocolor" | "--no-color" | "/nocolor" => {
                force_no_color = true;
            }
            "--no-errors" => {
                show_errors = false;
            }
            "--us-dates" => {
                us_dates = true;
            }
            "--config" | "-c" | "/config" => {
                if i + 1 < args.len() {
                    custom_config_path = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-h" | "--help" | "/?" | "/h" => {
                if query_args.is_empty() {
                    let enable_color = !force_no_color && env::var("NO_COLOR").is_err() && is_stdout_tty();
                    print_help_text(enable_color);
                    exit(0);
                }
            }
            "-v" | "-V" | "--version" => {
                if query_args.is_empty() {
                    let enable_color = !force_no_color && env::var("NO_COLOR").is_err() && is_stdout_tty();
                    print_version(enable_color);
                    exit(0);
                }
            }
            _ => {
                query_args.push(args[i].clone());
            }
        }
        i += 1;
    }

    let mut config = Config::load(custom_config_path.as_deref());
    if force_no_color {
        config.no_color = Some(true);
    }
    if us_dates {
        config.us_dates = Some(true);
    }

    let enable_color = !force_no_color && config.no_color != Some(true) && env::var("NO_COLOR").is_err();

    if interactive {
        run_interactive_mode(config, enable_color);
        exit(0);
    }

    if query_args.is_empty() {
        print_no_args_help(enable_color);
        exit(0);
    }

    let raw_query = query_args.join(" ");
    let status = execute_query_string(&raw_query, &config, enable_color, show_errors);
    exit(status);
}

pub fn execute_query_string(raw_query: &str, config: &Config, enable_color: bool, show_errors: bool) -> i32 {
    let mut lexer = Lexer::new(raw_query);
    let tokens = match lexer.tokenize() {
        Ok(t) => t,
        Err(e) => {
            print_error("query", &e, enable_color, show_errors);
            return 2;
        }
    };

    let mut parser = Parser::new(tokens, raw_query.to_string());
    let query = match parser.parse() {
        Ok(q) => q,
        Err(e) => {
            print_error("query", &e, enable_color, show_errors);
            return 2;
        }
    };

    let us_dates = config.us_dates.unwrap_or(false);

    // Collect all matching files from roots
    let mut all_files = Vec::new();
    for root in &query.roots {
        let res = traverse_root(root, config);
        if !res.errors.is_empty() {
            for err in &res.errors {
                print_error(&root.path, err, enable_color, show_errors);
            }
            return 1;
        }
        all_files.extend(res.files);
    }

    // Filter matching files by WHERE
    let mut matching_files = Vec::new();
    let empty_aliases = HashMap::new();

    for file in &all_files {
        let ctx = EvalContext {
            file,
            config,
            us_dates,
            aliases: &empty_aliases,
        };

        let is_match = if let Some(ref where_expr) = query.where_clause {
            match eval_expr(where_expr, &ctx) {
                Ok(val) => val.to_bool(),
                Err(e) => {
                    print_error("query", &e, enable_color, show_errors);
                    return 2;
                }
            }
        } else {
            true
        };

        if is_match {
            matching_files.push(file.clone());
        }
    }

    // Check if aggregate functions exist in fields
    let has_aggregates = query.fields.iter().any(is_aggregate_expr) || !query.group_by.is_empty();

    let mut format_rows = Vec::new();

    if has_aggregates {
        // Group files
        let mut groups: Vec<(Vec<Value>, Vec<FileInfo>)> = Vec::new();
        if query.group_by.is_empty() {
            groups.push((Vec::new(), matching_files));
        } else {
            let mut group_map: Vec<(Vec<Value>, Vec<FileInfo>)> = Vec::new();
            for file in matching_files {
                let ctx = EvalContext { file: &file, config, us_dates, aliases: &empty_aliases };
                let mut group_keys = Vec::new();
                for g_expr in &query.group_by {
                    group_keys.push(eval_expr(g_expr, &ctx).unwrap_or(Value::Null));
                }
                if let Some(existing) = group_map.iter_mut().find(|(k, _)| k == &group_keys) {
                    existing.1.push(file);
                } else {
                    group_map.push((group_keys, vec![file]));
                }
            }
            groups = group_map;
        }

        for (_key, group_files) in groups {
            let dummy_file = group_files.first().cloned();
            let mut row_vals = Vec::new();
            for field_expr in &query.fields {
                let val = eval_aggregate_expr(field_expr, &group_files, config, us_dates)?;
                row_vals.push(val);
            }
            format_rows.push(FormatRow { values: row_vals, file: dummy_file });
        }
    } else {
        for file in &matching_files {
            let ctx = EvalContext { file, config, us_dates, aliases: &empty_aliases };
            let mut row_vals = Vec::new();
            for field_expr in &query.fields {
                let val = match eval_expr(field_expr, &ctx) {
                    Ok(v) => v,
                    Err(e) => {
                        print_error("query", &e, enable_color, show_errors);
                        return 2;
                    }
                };
                row_vals.push(val);
            }
            format_rows.push(FormatRow { values: row_vals, file: Some(file.clone()) });
        }
    }

    // ORDER BY
    if !query.order_by.is_empty() {
        format_rows.sort_by(|a, b| {
            for order in &query.order_by {
                let (v_a, v_b) = if let Expr::Literal(Value::Integer(idx)) = order.expr {
                    let col_idx = (idx - 1) as usize;
                    (a.values.get(col_idx).cloned().unwrap_or(Value::Null), b.values.get(col_idx).cloned().unwrap_or(Value::Null))
                } else if let (Some(fa), Some(fb)) = (&a.file, &b.file) {
                    let ctx_a = EvalContext { file: fa, config, us_dates, aliases: &empty_aliases };
                    let ctx_b = EvalContext { file: fb, config, us_dates, aliases: &empty_aliases };
                    (eval_expr(&order.expr, &ctx_a).unwrap_or(Value::Null), eval_expr(&order.expr, &ctx_b).unwrap_or(Value::Null))
                } else {
                    (Value::Null, Value::Null)
                };

                let cmp = compare_values(&v_a, &v_b);
                if cmp != std::cmp::Ordering::Equal {
                    return if order.desc { cmp.reverse() } else { cmp };
                }
            }
            std::cmp::Ordering::Equal
        });
    }

    // OFFSET
    if let Some(off) = query.offset {
        if off < format_rows.len() {
            format_rows = format_rows[off..].to_vec();
        } else {
            format_rows.clear();
        }
    }

    // LIMIT
    if let Some(lim) = query.limit {
        if lim < format_rows.len() {
            format_rows.truncate(lim);
        }
    }

    let formatted = format_output(&query, &format_rows, config, enable_color);
    print!("{}", formatted);

    0
}

fn is_aggregate_expr(expr: &Expr) -> bool {
    match expr {
        Expr::FunctionCall(name, _) => {
            matches!(name.to_uppercase().as_str(), "MIN" | "MAX" | "AVG" | "SUM" | "COUNT" | "STDDEV_POP" | "STDDEV_SAMP" | "STDDEV" | "STD" | "VAR_POP" | "VAR_SAMP" | "VARIANCE")
        }
        Expr::BinaryOp(l, _, r) => is_aggregate_expr(l) || is_aggregate_expr(r),
        _ => false,
    }
}

fn eval_aggregate_expr(expr: &Expr, group_files: &[FileInfo], config: &Config, us_dates: bool) -> Result<Value, String> {
    let empty_aliases = HashMap::new();
    match expr {
        Expr::FunctionCall(name, args) => {
            let fn_name = name.to_uppercase();
            match fn_name.as_str() {
                "COUNT" => Ok(Value::Integer(group_files.len() as i64)),
                "MIN" => {
                    let mut min_val: Option<Value> = None;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(ref current_min) = min_val {
                            if compare_values(&val, current_min) == std::cmp::Ordering::Less {
                                min_val = Some(val);
                            }
                        } else {
                            min_val = Some(val);
                        }
                    }
                    Ok(min_val.unwrap_or(Value::Null))
                }
                "MAX" => {
                    let mut max_val: Option<Value> = None;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(ref current_max) = max_val {
                            if compare_values(&val, current_max) == std::cmp::Ordering::Greater {
                                max_val = Some(val);
                            }
                        } else {
                            max_val = Some(val);
                        }
                    }
                    Ok(max_val.unwrap_or(Value::Null))
                }
                "SUM" => {
                    let mut sum = 0.0;
                    let mut is_float = false;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() {
                            sum += n;
                            if val.to_i64().is_none() { is_float = true; }
                        }
                    }
                    if is_float || sum.fract() != 0.0 {
                        Ok(Value::Float(sum))
                    } else {
                        Ok(Value::Integer(sum as i64))
                    }
                }
                "AVG" => {
                    if group_files.is_empty() { return Ok(Value::Null); }
                    let mut sum = 0.0;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() {
                            sum += n;
                        }
                    }
                    Ok(Value::Float(sum / group_files.len() as f64))
                }
                "VAR_POP" | "VARIANCE" => {
                    if group_files.is_empty() { return Ok(Value::Null); }
                    let mut vals = Vec::new();
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() { vals.push(n); }
                    }
                    if vals.is_empty() { return Ok(Value::Null); }
                    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
                    let var = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / vals.len() as f64;
                    Ok(Value::Float(var))
                }
                "VAR_SAMP" => {
                    if group_files.len() <= 1 { return Ok(Value::Null); }
                    let mut vals = Vec::new();
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() { vals.push(n); }
                    }
                    if vals.len() <= 1 { return Ok(Value::Null); }
                    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
                    let var = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (vals.len() - 1) as f64;
                    Ok(Value::Float(var))
                }
                "STDDEV_POP" | "STDDEV" | "STD" => {
                    let var_val = eval_aggregate_expr(&Expr::FunctionCall("VAR_POP".to_string(), args.to_vec()), group_files, config, us_dates)?;
                    if let Some(v) = var_val.to_f64() {
                        Ok(Value::Float(v.sqrt()))
                    } else {
                        Ok(Value::Null)
                    }
                }
                "STDDEV_SAMP" => {
                    let var_val = eval_aggregate_expr(&Expr::FunctionCall("VAR_SAMP".to_string(), args.to_vec()), group_files, config, us_dates)?;
                    if let Some(v) = var_val.to_f64() {
                        Ok(Value::Float(v.sqrt()))
                    } else {
                        Ok(Value::Null)
                    }
                }
                _ => {
                    if let Some(first) = group_files.first() {
                        let ctx = EvalContext { file: first, config, us_dates, aliases: &empty_aliases };
                        eval_expr(expr, &ctx)
                    } else {
                        Ok(Value::Null)
                    }
                }
            }
        }
        _ => {
            if let Some(first) = group_files.first() {
                let ctx = EvalContext { file: first, config, us_dates, aliases: &empty_aliases };
                eval_expr(expr, &ctx)
            } else {
                Ok(Value::Null)
            }
        }
    }
}

fn compare_values(a: &Value, b: &Value) -> std::cmp::Ordering {
    if let (Some(na), Some(nb)) = (a.to_f64(), b.to_f64()) {
        na.partial_cmp(&nb).unwrap_or(std::cmp::Ordering::Equal)
    } else {
        a.to_string_repr().cmp(&b.to_string_repr())
    }
}
