{"command":"cat <<'EOF' > src/eval.rs
use std::collections::HashMap;
use chrono::{Datelike, Local, NaiveDate, NaiveDateTime};
use regex::Regex;

use crate::ast::*;
use crate::config::Config;
use crate::file_info::FileInfo;

pub fn glob_to_regex(glob: &str) -> String {
    let mut regex = String::from("^");
    for c in glob.chars() {
        match c {
            '*' => regex.push_str(".*"),
            '?' => regex.push('.'),
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '[' | ']' | '{' | '}' | '\\' => {
                regex.push('\\');
                regex.push(c);
            }
            _ => regex.push(c),
        }
    }
    regex.push('$');
    regex
}

pub fn like_to_regex(like: &str) -> String {
    let mut regex = String::from("^");
    for c in like.chars() {
        match c {
            '%' => regex.push_str(".*"),
            '_' => regex.push('.'),
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '[' | ']' | '{' | '}' | '\\' | '*' | '?' => {
                regex.push('\\');
                regex.push(c);
            }
            _ => regex.push(c),
        }
    }
    regex.push('$');
    regex
}

pub fn parse_date_spec(spec: &str, _us_dates: bool) -> Option<(NaiveDateTime, NaiveDateTime)> {
    let s = spec.trim().to_lowercase();
    let today = Local::now().naive_local().date();

    if s == "today" {
        let start = today.and_hms_opt(0, 0, 0)?;
        let end = today.and_hms_opt(23, 59, 59)?;
        return Some((start, end));
    }
    if s == "yesterday" {
        let yest = today.pred_opt()?;
        let start = yest.and_hms_opt(0, 0, 0)?;
        let end = yest.and_hms_opt(23, 59, 59)?;
        return Some((start, end));
    }

    // Try parsing YYYY-MM-DD HH:MM:SS
    if let Ok(dt) = NaiveDateTime::parse_from_str(spec, "%Y-%m-%d %H:%M:%S") {
        return Some((dt, dt));
    }

    // YYYY-MM-DD HH:MM
    if let Ok(dt) = NaiveDateTime::parse_from_str(spec, "%Y-%m-%d %H:%M") {
        let end_dt = dt + chrono::Duration::seconds(59);
        return Some((dt, end_dt));
    }

    // YYYY-MM-DD HH
    if let Ok(dt) = NaiveDateTime::parse_from_str(spec, "%Y-%m-%d %H") {
        let end_dt = dt + chrono::Duration::seconds(3599);
        return Some((dt, end_dt));
    }

    // YYYY-MM-DD
    if let Ok(d) = NaiveDate::parse_from_str(spec, "%Y-%m-%d") {
        let start = d.and_hms_opt(0, 0, 0)?;
        let end = d.and_hms_opt(23, 59, 59)?;
        return Some((start, end));
    }

    None
}

pub struct EvalContext<'a> {
    pub file: &'a FileInfo,
    pub config: &'a Config,
    pub us_dates: bool,
    pub aliases: &'a HashMap<String, FileInfo>,
}

pub fn eval_expr(expr: &Expr, ctx: &EvalContext) -> Result<Value, String> {
    match expr {
        Expr::Literal(val) => Ok(val.clone()),
        Expr::Column(col_name) => {
            if let Some((alias, field)) = col_name.split_once('.') {
                if let Some(aliased_file) = ctx.aliases.get(alias) {
                    return Ok(aliased_file.get_value(field, ctx.config));
                }
            }
            let val = ctx.file.get_value(col_name, ctx.config);
            if matches!(val, Value::Null) && !col_name.is_empty() {
                Ok(Value::String(col_name.clone()))
            } else {
                Ok(val)
            }
        }
        Expr::UnaryOp(Op::Not, inner) => {
            let val = eval_expr(inner, ctx)?;
            Ok(Value::Bool(!val.to_bool()))
        }
        Expr::BinaryOp(left, op, right) => {
            let v_left = eval_expr(left, ctx)?;
            let v_right = eval_expr(right, ctx)?;
            eval_binary_op(&v_left, op, &v_right, ctx)
        }
        Expr::Between(val_expr, low_expr, high_expr) => {
            let val = eval_expr(val_expr, ctx)?;
            let low = eval_expr(low_expr, ctx)?;
            let high = eval_expr(high_expr, ctx)?;
            let gte = eval_binary_op(&val, &Op::Gte, &low, ctx)?;
            let lte = eval_binary_op(&val, &Op::Lte, &high, ctx)?;
            Ok(Value::Bool(gte.to_bool() && lte.to_bool()))
        }
        Expr::InList(val_expr, list) => {
            let val = eval_expr(val_expr, ctx)?;
            for item_expr in list {
                let item_val = eval_expr(item_expr, ctx)?;
                let eq = eval_binary_op(&val, &Op::Eq, &item_val, ctx)?;
                if eq.to_bool() {
                    return Ok(Value::Bool(true));
                }
            }
            Ok(Value::Bool(false))
        }
        Expr::FunctionCall(fn_name, args) => eval_function(fn_name, args, ctx),
        _ => Ok(Value::Null),
    }
}

pub fn eval_binary_op(left: &Value, op: &Op, right: &Value, ctx: &EvalContext) -> Result<Value, String> {
    match op {
        Op::And => Ok(Value::Bool(left.to_bool() && right.to_bool())),
        Op::Or => Ok(Value::Bool(left.to_bool() || right.to_bool())),
        Op::Eq => {
            if let (Value::DateTime(dt), Value::String(s)) = (left, right) {
                if let Some((start, end)) = parse_date_spec(s, ctx.us_dates) {
                    return Ok(Value::Bool(*dt >= start && *dt <= end));
                }
            }
            let str_right = right.to_string_repr();
            if str_right.contains('*') || str_right.contains('?') {
                let rx_str = glob_to_regex(&str_right);
                if let Ok(rx) = Regex::new(&rx_str) {
                    return Ok(Value::Bool(rx.is_match(&left.to_string_repr())));
                }
            }
            if let (Some(l_num), Some(r_num)) = (left.to_f64(), right.to_f64()) {
                Ok(Value::Bool((l_num - r_num).abs() < 1e-9))
            } else {
                Ok(Value::Bool(left.to_string_repr() == str_right))
            }
        }
        Op::ExactEq => {
            Ok(Value::Bool(left.to_string_repr() == right.to_string_repr()))
        }
        Op::Ne => {
            let eq = eval_binary_op(left, &Op::Eq, right, ctx)?;
            Ok(Value::Bool(!eq.to_bool()))
        }
        Op::ExactNe => {
            Ok(Value::Bool(left.to_string_repr() != right.to_string_repr()))
        }
        Op::Lt => {
            if let (Some(l), Some(r)) = (left.to_f64(), right.to_f64()) {
                Ok(Value::Bool(l < r))
            } else {
                Ok(Value::Bool(left.to_string_repr() < right.to_string_repr()))
            }
        }
        Op::Lte => {
            if let (Some(l), Some(r)) = (left.to_f64(), right.to_f64()) {
                Ok(Value::Bool(l <= r))
            } else {
                Ok(Value::Bool(left.to_string_repr() <= right.to_string_repr()))
            }
        }
        Op::Gt => {
            if let (Some(l), Some(r)) = (left.to_f64(), right.to_f64()) {
                Ok(Value::Bool(l > r))
            } else {
                Ok(Value::Bool(left.to_string_repr() > right.to_string_repr()))
            }
        }
        Op::Gte => {
            if let (Some(l), Some(r)) = (left.to_f64(), right.to_f64()) {
                Ok(Value::Bool(l >= r))
            } else {
                Ok(Value::Bool(left.to_string_repr() >= right.to_string_repr()))
            }
        }
        Op::RegexMatch => {
            let pattern = right.to_string_repr();
            if let Ok(rx) = Regex::new(&pattern) {
                Ok(Value::Bool(rx.is_match(&left.to_string_repr())))
            } else {
                Ok(Value::Bool(false))
            }
        }
        Op::RegexNoMatch => {
            let match_val = eval_binary_op(left, &Op::RegexMatch, right, ctx)?;
            Ok(Value::Bool(!match_val.to_bool()))
        }
        Op::Like => {
            let rx_str = like_to_regex(&right.to_string_repr());
            if let Ok(rx) = Regex::new(&rx_str) {
                Ok(Value::Bool(rx.is_match(&left.to_string_repr())))
            } else {
                Ok(Value::Bool(false))
            }
        }
        Op::NotLike => {
            let like_val = eval_binary_op(left, &Op::Like, right, ctx)?;
            Ok(Value::Bool(!like_val.to_bool()))
        }
        Op::Add => {
            if let (Some(l), Some(r)) = (left.to_f64(), right.to_f64()) {
                if l.fract() == 0.0 && r.fract() == 0.0 {
                    Ok(Value::Integer((l + r) as i64))
                } else {
                    Ok(Value::Float(l + r))
                }
            } else {
                Ok(Value::String(format!("{}{}", left.to_string_repr(), right.to_string_repr())))
            }
        }
        Op::Sub => {
            let l = left.to_f64().unwrap_or(0.0);
            let r = right.to_f64().unwrap_or(0.0);
            if l.fract() == 0.0 && r.fract() == 0.0 {
                Ok(Value::Integer((l - r) as i64))
            } else {
                Ok(Value::Float(l - r))
            }
        }
        Op::Mul => {
            let l = left.to_f64().unwrap_or(0.0);
            let r = right.to_f64().unwrap_or(0.0);
            if l.fract() == 0.0 && r.fract() == 0.0 {
                Ok(Value::Integer((l * r) as i64))
            } else {
                Ok(Value::Float(l * r))
            }
        }
        Op::Div => {
            let l = left.to_f64().unwrap_or(0.0);
            let r = right.to_f64().unwrap_or(1.0);
            if r == 0.0 {
                Ok(Value::Null)
            } else if l.fract() == 0.0 && r.fract() == 0.0 && (l as i64) % (r as i64) == 0 {
                Ok(Value::Integer((l / r) as i64))
            } else {
                Ok(Value::Float(l / r))
            }
        }
        Op::Mod => {
            let l = left.to_i64().unwrap_or(0);
            let r = right.to_i64().unwrap_or(1);
            if r == 0 {
                Ok(Value::Null)
            } else {
                Ok(Value::Integer(l % r))
            }
        }
        _ => Ok(Value::Null),
    }
}

pub fn eval_function(fn_name: &str, args: &[Expr], ctx: &EvalContext) -> Result<Value, String> {
    let name = fn_name.to_uppercase();
    match name.as_str() {
        "LOWER" | "LOWERCASE" | "LCASE" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            Ok(Value::String(val.to_string_repr().to_lowercase()))
        }
        "UPPER" | "UPPERCASE" | "UCASE" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            Ok(Value::String(val.to_string_repr().to_uppercase()))
        }
        "INITCAP" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let s = val.to_string_repr();
            let mut result = String::new();
            let mut capitalize_next = true;
            for c in s.chars() {
                if c.is_alphanumeric() {
                    if capitalize_next {
                        result.extend(c.to_uppercase());
                        capitalize_next = false;
                    } else {
                        result.extend(c.to_lowercase());
                    }
                } else {
                    result.push(c);
                    capitalize_next = true;
                }
            }
            Ok(Value::String(result))
        }
        "LENGTH" | "LEN" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            Ok(Value::Integer(val.to_string_repr().chars().count() as i64))
        }
        "TO_BASE64" | "BASE64" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            use base64::Engine;
            Ok(Value::String(base64::engine::general_purpose::STANDARD.encode(val.to_string_repr())))
        }
        "FROM_BASE64" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            use base64::Engine;
            if let Ok(bytes) = base64::engine::general_purpose::STANDARD.decode(val.to_string_repr()) {
                Ok(Value::String(String::from_utf8_lossy(&bytes).to_string()))
            } else {
                Ok(Value::Null)
            }
        }
        "CONCAT" => {
            let mut s = String::new();
            for arg in args {
                s.push_str(&eval_expr(arg, ctx)?.to_string_repr());
            }
            Ok(Value::String(s))
        }
        "CONCAT_WS" => {
            if args.is_empty() {
                return Ok(Value::String("".to_string()));
            }
            let sep = eval_expr(&args[0], ctx)?.to_string_repr();
            let mut parts = Vec::new();
            for arg in &args[1..] {
                parts.push(eval_expr(arg, ctx)?.to_string_repr());
            }
            Ok(Value::String(parts.join(&sep)))
        }
        "LOCATE" | "POSITION" => {
            let s = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_string_repr() } else { "".into() };
            let sub = if args.len() > 1 { eval_expr(&args[1], ctx)?.to_string_repr() } else { "".into() };
            if let Some(pos) = s.find(&sub) {
                let char_idx = s[..pos].chars().count() + 1;
                Ok(Value::Integer(char_idx as i64))
            } else {
                Ok(Value::Integer(0))
            }
        }
        "SUBSTR" | "SUBSTRING" => {
            let s = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_string_repr() } else { "".into() };
            let pos = if args.len() > 1 { eval_expr(&args[1], ctx)?.to_i64().unwrap_or(1) } else { 1 };
            let len = if args.len() > 2 { eval_expr(&args[2], ctx)?.to_i64() } else { None };

            let char_count = s.chars().count();
            let start = if pos > 0 { (pos - 1) as usize } else { 0 };
            if start >= char_count {
                return Ok(Value::String("".to_string()));
            }
            let end = if let Some(l) = len {
                (start + l as usize).min(char_count)
            } else {
                char_count
            };
            let sub: String = s.chars().skip(start).take(end - start).collect();
            Ok(Value::String(sub))
        }
        "REPLACE" => {
            let s = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_string_repr() } else { "".into() };
            let from = if args.len() > 1 { eval_expr(&args[1], ctx)?.to_string_repr() } else { "".into() };
            let to = if args.len() > 2 { eval_expr(&args[2], ctx)?.to_string_repr() } else { "".into() };
            Ok(Value::String(s.replace(&from, &to)))
        }
        "TRIM" => {
            let s = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_string_repr() } else { "".into() };
            Ok(Value::String(s.trim().to_string()))
        }
        "LTRIM" => {
            let s = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_string_repr() } else { "".into() };
            Ok(Value::String(s.trim_start().to_string()))
        }
        "RTRIM" => {
            let s = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_string_repr() } else { "".into() };
            Ok(Value::String(s.trim_end().to_string()))
        }
        "BIN" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            Ok(Value::String(format!("{:b}", val)))
        }
        "HEX" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            Ok(Value::String(format!("{:x}", val)))
        }
        "OCT" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            Ok(Value::String(format!("{:o}", val)))
        }
        "ABS" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_f64().unwrap_or(0.0) } else { 0.0 };
            if val.fract() == 0.0 {
                Ok(Value::Integer(val.abs() as i64))
            } else {
                Ok(Value::Float(val.abs()))
            }
        }
        "POWER" | "POW" => {
            let base = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_f64().unwrap_or(0.0) } else { 0.0 };
            let exp = if args.len() > 1 { eval_expr(&args[1], ctx)?.to_f64().unwrap_or(0.0) } else { 0.0 };
            let res = base.powf(exp);
            if res.fract() == 0.0 {
                Ok(Value::Integer(res as i64))
            } else {
                Ok(Value::Float(res))
            }
        }
        "SQRT" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_f64().unwrap_or(0.0) } else { 0.0 };
            let res = val.sqrt();
            if res.fract() == 0.0 {
                Ok(Value::Integer(res as i64))
            } else {
                Ok(Value::Float(res))
            }
        }
        "FLOOR" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_f64().unwrap_or(0.0) } else { 0.0 };
            Ok(Value::Integer(val.floor() as i64))
        }
        "CEIL" | "CEILING" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_f64().unwrap_or(0.0) } else { 0.0 };
            Ok(Value::Integer(val.ceil() as i64))
        }
        "ROUND" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_f64().unwrap_or(0.0) } else { 0.0 };
            let decimals = if args.len() > 1 { eval_expr(&args[1], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            let mult = 10f64.powi(decimals as i32);
            let res = (val * mult).round() / mult;
            if decimals == 0 {
                Ok(Value::Integer(res as i64))
            } else {
                Ok(Value::Float(res))
            }
        }
        "PI" => Ok(Value::Float(std::f64::consts::PI)),

        "YEAR" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            if let Value::DateTime(dt) = val {
                Ok(Value::Integer(dt.year() as i64))
            } else if let Ok(dt) = NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S") {
                Ok(Value::Integer(dt.year() as i64))
            } else {
                Ok(Value::Null)
            }
        }
        "MONTH" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            if let Value::DateTime(dt) = val {
                Ok(Value::Integer(dt.month() as i64))
            } else if let Ok(dt) = NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S") {
                Ok(Value::Integer(dt.month() as i64))
            } else {
                Ok(Value::Null)
            }
        }
        "DAY" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            if let Value::DateTime(dt) = val {
                Ok(Value::Integer(dt.day() as i64))
            } else if let Ok(dt) = NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S") {
                Ok(Value::Integer(dt.day() as i64))
            } else {
                Ok(Value::Null)
            }
        }
        "DAYOFWEEK" | "DOW" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let dt_opt = match val {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            if let Some(dt) = dt_opt {
                let num = dt.weekday().number_from_sunday();
                Ok(Value::Integer(num as i64))
            } else {
                Ok(Value::Null)
            }
        }
        "DAYNAME" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let dt_opt = match val {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            if let Some(dt) = dt_opt {
                Ok(Value::String(dt.weekday().to_string()))
            } else {
                Ok(Value::Null)
            }
        }
        "DAYOFYEAR" | "DOY" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let dt_opt = match val {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            if let Some(dt) = dt_opt {
                Ok(Value::Integer(dt.ordinal() as i64))
            } else {
                Ok(Value::Null)
            }
        }
        "DATE_ADD" | "DATEADD" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let days = if args.len() > 1 { eval_expr(&args[1], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            let dt_opt = match val {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            if let Some(dt) = dt_opt {
                let res = dt + chrono::Duration::days(days);
                Ok(Value::DateTime(res))
            } else {
                Ok(Value::Null)
            }
        }
        "DATE_SUB" | "DATESUB" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let days = if args.len() > 1 { eval_expr(&args[1], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            let dt_opt = match val {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            if let Some(dt) = dt_opt {
                let res = dt - chrono::Duration::days(days);
                Ok(Value::DateTime(res))
            } else {
                Ok(Value::Null)
            }
        }
        "DATE_DIFF" | "DATEDIFF" => {
            let val1 = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let val2 = if args.len() > 1 { eval_expr(&args[1], ctx)? } else { Value::Null };
            let dt1 = match val1 {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val1.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            let dt2 = match val2 {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val2.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            if let (Some(d1), Some(d2)) = (dt1, dt2) {
                let diff = d1.signed_duration_since(d2).num_days();
                Ok(Value::Integer(diff))
            } else {
                Ok(Value::Null)
            }
        }
        "FROM_UNIXTIME" => {
            let ts = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            if let Some(dt) = DateTime::from_timestamp(ts, 0) {
                Ok(Value::DateTime(dt.naive_local()))
            } else {
                Ok(Value::Null)
            }
        }
        "LAST_DAY" | "LAST_DATE" => {
            let val = if !args.is_empty() { eval_expr(&args[0], ctx)? } else { Value::Null };
            let dt_opt = match val {
                Value::DateTime(dt) => Some(dt),
                _ => NaiveDateTime::parse_from_str(&val.to_string_repr(), "%Y-%m-%d %H:%M:%S").ok(),
            };
            if let Some(dt) = dt_opt {
                let (y, m) = (dt.year(), dt.month());
                let next_month = if m == 12 {
                    NaiveDate::from_ymd_opt(y + 1, 1, 1)
                } else {
                    NaiveDate::from_ymd_opt(y, m + 1, 1)
                };
                if let Some(nm) = next_month {
                    if let Some(last) = nm.pred_opt() {
                        return Ok(Value::String(last.format("%Y-%m-%d").to_string()));
                    }
                }
            }
            Ok(Value::Null)
        }
        "FORMAT_SIZE" | "FORMAT_FILESIZE" => {
            let sz = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_i64().unwrap_or(0) as u64 } else { 0 };
            Ok(Value::String(crate::file_info::format_file_size(sz)))
        }
        "FORMAT_TIME" | "PRETTY_TIME" => {
            let secs = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_i64().unwrap_or(0) } else { 0 };
            let days = secs / 86400;
            let hours = (secs % 86400) / 3600;
            let mins = (secs % 3600) / 60;
            let rem_secs = secs % 60;
            let mut parts = Vec::new();
            if days > 0 { parts.push(format!("{}d", days)); }
            if hours > 0 { parts.push(format!("{}h", hours)); }
            if mins > 0 { parts.push(format!("{}m", mins)); }
            if rem_secs > 0 || parts.is_empty() { parts.push(format!("{}s", rem_secs)); }
            Ok(Value::String(parts.join(",")))
        }
        "CURRENT_UID" => {
            Ok(Value::Integer(nix::unistd::getuid().as_raw() as i64))
        }
        "CURRENT_USER" => {
            let uid = nix::unistd::getuid();
            let name = nix::unistd::User::from_uid(uid).ok().flatten().map(|u| u.name).unwrap_or_default();
            Ok(Value::String(name))
        }
        "CURRENT_GID" => {
            Ok(Value::Integer(nix::unistd::getgid().as_raw() as i64))
        }
        "CURRENT_GROUP" => {
            let gid = nix::unistd::getgid();
            let name = nix::unistd::Group::from_gid(gid).ok().flatten().map(|g| g.name).unwrap_or_default();
            Ok(Value::String(name))
        }
        "CONTAINS" => {
            let needle = if !args.is_empty() { eval_expr(&args[0], ctx)?.to_string_repr() } else { "".into() };
            if ctx.file.is_file() {
                if let Ok(content) = std::fs::read_to_string(&ctx.file.full_path) {
                    return Ok(Value::Bool(content.contains(&needle)));
                }
            }
            Ok(Value::Bool(false))
        }
        "COALESCE" => {
            for arg in args {
                let v = eval_expr(arg, ctx)?;
                let s = v.to_string_repr();
                if !s.is_empty() && !matches!(v, Value::Null) {
                    return Ok(v);
                }
            }
            Ok(Value::Null)
        }
        _ => Ok(Value::Null),
    }
}
EOF"}

