    let query = match parser.parse() {
        Ok(q) => q,
        Err(e) => {
            print_error("query", &e, enable_color, show_errors);
            return 2;
        }
    };

    let us_dates = config.us_dates.unwrap_or(false);

    // Collect all matching files from roots
    let mut all_files = Vec::new();
    for root in &query.roots {
        let res = traverse_root(root, config);
        if !res.errors.is_empty() {
            for err in &res.errors {
                print_error(&root.path, err, enable_color, show_errors);
            }
            return 1;
        }
        all_files.extend(res.files);
    }

    // Filter matching files by WHERE
    let mut matching_files = Vec::new();
    let empty_aliases = HashMap::new();

    for file in &all_files {
        let ctx = EvalContext {
            file,
            config,
            us_dates,
            aliases: &empty_aliases,
        };

        let is_match = if let Some(ref where_expr) = query.where_clause {
            match eval_expr(where_expr, &ctx) {
                Ok(val) => val.to_bool(),
                Err(e) => {
                    print_error("query", &e, enable_color, show_errors);
                    return 2;
                }
            }
        } else {
            true
        };

        if is_match {
            matching_files.push(file.clone());
        }
    }

    let has_aggregates = query.fields.iter().any(is_aggregate_expr) || !query.group_by.is_empty();

    let mut format_rows = Vec::new();

    if has_aggregates {
        let mut groups: Vec<(Vec<Value>, Vec<FileInfo>)> = Vec::new();
        if query.group_by.is_empty() {
            groups.push((Vec::new(), matching_files));
        } else {
            let mut group_map: Vec<(Vec<Value>, Vec<FileInfo>)> = Vec::new();
            for file in matching_files {
                let ctx = EvalContext { file: &file, config, us_dates, aliases: &empty_aliases };
                let mut group_keys = Vec::new();
                for g_expr in &query.group_by {
                    group_keys.push(eval_expr(g_expr, &ctx).unwrap_or(Value::Null));
                }
                if let Some(existing) = group_map.iter_mut().find(|(k, _)| k == &group_keys) {
                    existing.1.push(file);
                } else {
                    group_map.push((group_keys, vec![file]));
                }
            }
            groups = group_map;
        }

        for (_key, group_files) in groups {
            let dummy_file = group_files.first().cloned();
            let mut row_vals = Vec::new();
            for field_expr in &query.fields {
                let val = match eval_aggregate_expr(field_expr, &group_files, config, us_dates) {
                    Ok(v) => v,
                    Err(e) => {
                        print_error("query", &e, enable_color, show_errors);
                        return 2;
                    }
                };
                row_vals.push(val);
            }
            format_rows.push(FormatRow { values: row_vals, file: dummy_file });
        }
    } else {
        for file in &matching_files {
            let ctx = EvalContext { file, config, us_dates, aliases: &empty_aliases };
