            for field_expr in &query.fields {
                let val = match eval_expr(field_expr, &ctx) {
                    Ok(v) => v,
                    Err(e) => {
                        print_error("query", &e, enable_color, show_errors);
                        return 2;
                    }
                };
                row_vals.push(val);
            }
            format_rows.push(FormatRow { values: row_vals, file: Some(file.clone()) });
        }
    }

    // ORDER BY
    if !query.order_by.is_empty() {
        format_rows.sort_by(|a, b| {
            for order in &query.order_by {
                let (v_a, v_b) = if let Expr::Literal(Value::Integer(idx)) = order.expr {
