        }
        Expr::BinaryOp(l, _, r) => is_aggregate_expr(l) || is_aggregate_expr(r),
        _ => false,
    }
}

fn eval_aggregate_expr(expr: &Expr, group_files: &[FileInfo], config: &Config, us_dates: bool) -> Result<Value, String> {
    let empty_aliases = HashMap::new();
    match expr {
        Expr::FunctionCall(name, args) => {
            let fn_name = name.to_uppercase();
            match fn_name.as_str() {
                "COUNT" => Ok(Value::Integer(group_files.len() as i64)),
                "MIN" => {
                    let mut min_val: Option<Value> = None;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(ref current_min) = min_val {
                            if compare_values(&val, current_min) == std::cmp::Ordering::Less {
                                min_val = Some(val);
                            }
                        } else {
                            min_val = Some(val);
                        }
                    }
                    Ok(min_val.unwrap_or(Value::Null))
                }
                "MAX" => {
                    let mut max_val: Option<Value> = None;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(ref current_max) = max_val {
                            if compare_values(&val, current_max) == std::cmp::Ordering::Greater {
                                max_val = Some(val);
                            }
                        } else {
                            max_val = Some(val);
                        }
                    }
                    Ok(max_val.unwrap_or(Value::Null))
                }
                "SUM" => {
                    let mut sum = 0.0;
                    let mut is_float = false;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() {
                            sum += n;
                            if val.to_i64().is_none() { is_float = true; }
                        }
                    }
                    if is_float || sum.fract() != 0.0 {
                        Ok(Value::Float(sum))
                    } else {
                        Ok(Value::Integer(sum as i64))
                    }
                }
                "AVG" => {
                    if group_files.is_empty() { return Ok(Value::Null); }
                    let mut sum = 0.0;
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() {
                            sum += n;
                        }
                    }
                    Ok(Value::Float(sum / group_files.len() as f64))
                }
                "VAR_POP" | "VARIANCE" => {
                    if group_files.is_empty() { return Ok(Value::Null); }
                    let mut vals = Vec::new();
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() { vals.push(n); }
                    }
                    if vals.is_empty() { return Ok(Value::Null); }
                    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
                    let var = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / vals.len() as f64;
                    Ok(Value::Float(var))
                }
                "VAR_SAMP" => {
                    if group_files.len() <= 1 { return Ok(Value::Null); }
                    let mut vals = Vec::new();
                    for f in group_files {
                        let ctx = EvalContext { file: f, config, us_dates, aliases: &empty_aliases };
                        let val = if !args.is_empty() { eval_expr(&args[0], &ctx)? } else { Value::Null };
                        if let Some(n) = val.to_f64() { vals.push(n); }
                    }
                    if vals.len() <= 1 { return Ok(Value::Null); }
                    let mean = vals.iter().sum::<f64>() / vals.len() as f64;
                    let var = vals.iter().map(|v| (v - mean).powi(2)).sum::<f64>() / (vals.len() - 1) as f64;
                    Ok(Value::Float(var))
                }
                "STDDEV_POP" | "STDDEV" | "STD" => {
                    let var_val = eval_aggregate_expr(&Expr::FunctionCall("VAR_POP".to_string(), args.to_vec()), group_files, config, us_dates)?;
                    if let Some(v) = var_val.to_f64() {
