use std::fs::{self, Metadata};
use std::os::unix::fs::MetadataExt;
use std::path::PathBuf;
use chrono::{DateTime, Local, NaiveDateTime, TimeZone};

use crate::ast::Value;
use crate::config::Config;
use crate::hashes;

#[derive(Debug, Clone)]
pub struct FileInfo {
    pub path: PathBuf,            // relative path
    pub full_path: PathBuf,       // full/absolute path
    pub _root_path: PathBuf,      // search root
    pub archive_prefix: Option<String>,
    pub _is_archive_entry: bool,
    pub metadata: Option<Metadata>,
}

pub fn format_file_size(size: u64) -> String {
    if size < 1024 {
        format!("{}B", size)
    } else {
        let units = ["KiB", "MiB", "GiB", "TiB", "PiB"];
        let mut s = size as f64 / 1024.0;
        let mut u = 0;
        while s >= 1024.0 && u < units.len() - 1 {
            s /= 1024.0;
            u += 1;
        }
        let formatted = format!("{:.2}", s);
        let trimmed = if formatted.ends_with(".00") {
            formatted[..formatted.len() - 3].to_string()
        } else {
            formatted
        };
        format!("{}{}", trimmed, units[u])
    }
}

pub fn format_mode_unix(mode: u32, is_dir: bool, is_symlink: bool) -> String {
    let mut s = String::with_capacity(10);
    if is_symlink {
        s.push('l');
    } else if is_dir {
        s.push('d');
    } else {
        let file_type = mode & 0xF000;
        match file_type {
            0x1000 => s.push('p'),
            0x2000 => s.push('c'),
            0x6000 => s.push('b'),
            0xC000 => s.push('s'),
            _ => s.push('-'),
        }
    }

    s.push(if (mode & 0o400) != 0 { 'r' } else { '-' });
    s.push(if (mode & 0o200) != 0 { 'w' } else { '-' });
    let suid = (mode & 0o4000) != 0;
    let uexec = (mode & 0o100) != 0;
    s.push(match (suid, uexec) {
        (false, false) => '-',
        (false, true) => 'x',
        (true, false) => 'S',
        (true, true) => 's',
    });

    s.push(if (mode & 0o040) != 0 { 'r' } else { '-' });
    s.push(if (mode & 0o020) != 0 { 'w' } else { '-' });
    let sgid = (mode & 0o2000) != 0;
    let gexec = (mode & 0o010) != 0;
    s.push(match (sgid, gexec) {
        (false, false) => '-',
        (false, true) => 'x',
        (true, false) => 'S',
        (true, true) => 's',
    });

    s.push(if (mode & 0o004) != 0 { 'r' } else { '-' });
    s.push(if (mode & 0o002) != 0 { 'w' } else { '-' });
    let sticky = (mode & 0o1000) != 0;
    let oexec = (mode & 0o001) != 0;
    s.push(match (sticky, oexec) {
        (false, false) => '-',
        (false, true) => 'x',
        (true, false) => 'T',
        (true, true) => 't',
    });

    s
}

impl FileInfo {
    pub fn get_value(&self, field_name: &str, config: &Config) -> Value {
        let name_lower = field_name.to_lowercase();
        let name_clean = name_lower.trim_matches('`').trim_matches('"');

        match name_clean {
            "name" => Value::String(self.name()),
            "fname" | "filename" => Value::String(self.fname()),
            "ext" | "extension" => Value::String(self.ext()),
            "path" => Value::String(self.relative_path_string()),
            "abspath" => Value::String(self.abspath_string()),
            "dir" | "dirname" | "directory" => Value::String(self.dir_string()),
            "absdir" => Value::String(self.absdir_string()),
            "size" => Value::Integer(self.size() as i64),
            "fsize" | "hsize" => Value::String(format_file_size(self.size())),

            "created" => self.created_datetime().map(Value::DateTime).unwrap_or(Value::Null),
            "accessed" => self.accessed_datetime().map(Value::DateTime).unwrap_or(Value::Null),
            "modified" => self.modified_datetime().map(Value::DateTime).unwrap_or(Value::Null),

            "atime" => Value::Integer(self.atime()),
            "mtime" => Value::Integer(self.mtime()),
            "ctime" => Value::Integer(self.ctime()),

            "is_dir" => Value::Bool(self.is_dir()),
            "is_file" => Value::Bool(self.is_file()),
            "is_symlink" => Value::Bool(self.is_symlink()),
            "is_pipe" | "is_fifo" => Value::Bool(self.is_pipe()),
            "is_char" | "is_character" => Value::Bool(self.is_char()),
            "is_block" => Value::Bool(self.is_block()),
            "is_socket" => Value::Bool(self.is_socket()),
            "is_hidden" => Value::Bool(self.is_hidden()),
            "is_empty" => Value::Bool(self.is_empty()),
            "is_shebang" => Value::Bool(self.is_shebang()),
            "is_binary" => Value::Bool(self.is_binary()),
            "is_text" => Value::Bool(self.is_text()),

            "is_archive" => Value::Bool(config.is_ext_match(&self.ext(), "archive")),
            "is_audio" => Value::Bool(config.is_ext_match(&self.ext(), "audio")),
            "is_book" => Value::Bool(config.is_ext_match(&self.ext(), "book")),
            "is_doc" => Value::Bool(config.is_ext_match(&self.ext(), "doc")),
            "is_font" => Value::Bool(config.is_ext_match(&self.ext(), "font")),
            "is_image" => Value::Bool(config.is_ext_match(&self.ext(), "image")),
            "is_source" => Value::Bool(config.is_ext_match(&self.ext(), "source")),
            "is_video" => Value::Bool(config.is_ext_match(&self.ext(), "video")),

            "mode" => Value::String(self.mode_string()),
            "uid" => Value::Integer(self.uid() as i64),
            "gid" => Value::Integer(self.gid() as i64),
            "user" => Value::String(self.user_name()),
            "group" => Value::String(self.group_name()),

            "user_read" => Value::Bool((self.mode_bits() & 0o400) != 0),
            "user_write" => Value::Bool((self.mode_bits() & 0o200) != 0),
            "user_exec" => Value::Bool((self.mode_bits() & 0o100) != 0),
            "user_all" | "user_rwx" => Value::Bool((self.mode_bits() & 0o700) == 0o700),

            "group_read" => Value::Bool((self.mode_bits() & 0o040) != 0),
            "group_write" => Value::Bool((self.mode_bits() & 0o020) != 0),
            "group_exec" => Value::Bool((self.mode_bits() & 0o010) != 0),
            "group_all" | "group_rwx" => Value::Bool((self.mode_bits() & 0o070) == 0o070),

            "other_read" => Value::Bool((self.mode_bits() & 0o004) != 0),
            "other_write" => Value::Bool((self.mode_bits() & 0o002) != 0),
            "other_exec" => Value::Bool((self.mode_bits() & 0o001) != 0),
            "other_all" | "other_rwx" => Value::Bool((self.mode_bits() & 0o007) == 0o007),

            "suid" | "is_suid" => Value::Bool((self.mode_bits() & 0o4000) != 0),
            "sgid" | "is_sgid" => Value::Bool((self.mode_bits() & 0o2000) != 0),
            "sticky" | "is_sticky" => Value::Bool((self.mode_bits() & 0o1000) != 0),

            "device" => Value::Integer(self.device() as i64),
            "rdev" => Value::Integer(self.rdev() as i64),
            "inode" => Value::Integer(self.inode() as i64),
            "blocks" => Value::Integer(self.blocks() as i64),
            "hardlinks" => Value::Integer(self.nlink() as i64),

            "sha1" => Value::String(self.sha1()),
            "sha2_256" | "sha256" => Value::String(self.sha256()),
            "sha2_512" | "sha512" => Value::String(self.sha512()),
            "sha3_512" | "sha3" => Value::String("".to_string()),
            "md5" => Value::String(self.md5()),

            "mime" => Value::String(self.mime_type()),

            _ => Value::Null,
        }
    }

    pub fn name(&self) -> String {
        self.path.file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| self.path.to_string_lossy().to_string())
    }

    pub fn fname(&self) -> String {
        self.path.file_stem()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| "".to_string())
    }

    pub fn ext(&self) -> String {
        self.path.extension()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| "".to_string())
    }

    pub fn relative_path_string(&self) -> String {
        if let Some(prefix) = &self.archive_prefix {
            let rel = self.path.to_string_lossy().to_string();
            format!("{} {}", prefix, rel)
        } else {
            let s = self.path.to_string_lossy().to_string();
            if s.starts_with("./") {
                s[2..].to_string()
            } else {
                s
            }
        }
    }

    pub fn abspath_string(&self) -> String {
        let abs = if self.full_path.is_absolute() {
            self.full_path.clone()
        } else {
            std::env::current_dir().unwrap_or_default().join(&self.full_path)
        };
        let abs_str = abs.to_string_lossy().to_string();

        if let Some(prefix) = &self.archive_prefix {
            format!("{} {}", prefix, self.path.to_string_lossy())
        } else {
            abs_str
        }
    }

    pub fn dir_string(&self) -> String {
        self.path.parent()
            .map(|p| {
                let s = p.to_string_lossy().to_string();
                if s.starts_with("./") {
                    s[2..].to_string()
                } else {
                    s
                }
            })
            .unwrap_or_else(|| "".to_string())
    }

    pub fn absdir_string(&self) -> String {
        let abs = if self.full_path.is_absolute() {
            self.full_path.clone()
        } else {
            std::env::current_dir().unwrap_or_default().join(&self.full_path)
        };
        abs.parent()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|| "".to_string())
    }

    pub fn size(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.len()).unwrap_or(0)
    }

    pub fn is_dir(&self) -> bool {
        self.metadata.as_ref().map(|m| m.is_dir()).unwrap_or(false)
    }

    pub fn is_file(&self) -> bool {
        self.metadata.as_ref().map(|m| m.is_file()).unwrap_or(false)
    }

    pub fn is_symlink(&self) -> bool {
        self.metadata.as_ref().map(|m| m.file_type().is_symlink()).unwrap_or(false)
    }

    pub fn is_pipe(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0x1000).unwrap_or(false)
    }

    pub fn is_char(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0x2000).unwrap_or(false)
    }

    pub fn is_block(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0x6000).unwrap_or(false)
    }

    pub fn is_socket(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0xC000).unwrap_or(false)
    }

    pub fn is_hidden(&self) -> bool {
        self.name().starts_with('.')
    }

    pub fn is_empty(&self) -> bool {
        if self.is_dir() {
            fs::read_dir(&self.full_path).map(|mut d| d.next().is_none()).unwrap_or(true)
        } else {
            self.size() == 0
        }
    }

    pub fn is_shebang(&self) -> bool {
        if self.is_file() && self.size() >= 2 {
            if let Ok(data) = fs::read(&self.full_path) {
                return data.starts_with(b"#!");
            }
        }
        false
    }

    pub fn is_binary(&self) -> bool {
        let mime = self.mime_type();
        !mime.starts_with("text/") && mime != "application/json" && mime != "application/javascript" && mime != "application/xml"
    }

    pub fn is_text(&self) -> bool {
        !self.is_binary()
    }

    pub fn mode_bits(&self) -> u32 {
        self.metadata.as_ref().map(|m| m.mode()).unwrap_or(0)
    }

    pub fn mode_string(&self) -> String {
        format_mode_unix(self.mode_bits(), self.is_dir(), self.is_symlink())
    }

    pub fn uid(&self) -> u32 {
        self.metadata.as_ref().map(|m| m.uid()).unwrap_or(0)
    }

    pub fn gid(&self) -> u32 {
        self.metadata.as_ref().map(|m| m.gid()).unwrap_or(0)
    }

    pub fn user_name(&self) -> String {
        nix::unistd::User::from_uid(nix::unistd::Uid::from_raw(self.uid()))
            .ok()
            .flatten()
            .map(|u| u.name)
            .unwrap_or_else(|| self.uid().to_string())
    }

    pub fn group_name(&self) -> String {
        nix::unistd::Group::from_gid(nix::unistd::Gid::from_raw(self.gid()))
            .ok()
            .flatten()
            .map(|g| g.name)
            .unwrap_or_else(|| self.gid().to_string())
    }

    pub fn device(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.dev()).unwrap_or(0)
    }

    pub fn rdev(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.rdev()).unwrap_or(0)
    }

    pub fn inode(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.ino()).unwrap_or(0)
    }

    pub fn blocks(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.blocks()).unwrap_or(0)
    }

    pub fn nlink(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.nlink()).unwrap_or(1)
    }

    pub fn atime(&self) -> i64 {
        self.metadata.as_ref().map(|m| m.atime()).unwrap_or(0)
    }

    pub fn mtime(&self) -> i64 {
        self.metadata.as_ref().map(|m| m.mtime()).unwrap_or(0)
    }

    pub fn ctime(&self) -> i64 {
        self.metadata.as_ref().map(|m| m.ctime()).unwrap_or(0)
    }

    pub fn created_datetime(&self) -> Option<NaiveDateTime> {
        self.metadata.as_ref()
            .and_then(|m| m.created().ok())
            .map(|t| {
                let dt: DateTime<Local> = DateTime::from(t);
                dt.naive_local()
            })
    }

    pub fn accessed_datetime(&self) -> Option<NaiveDateTime> {
        let ts = self.atime();
        Local.timestamp_opt(ts, 0).single().map(|dt| dt.naive_local())
    }

    pub fn modified_datetime(&self) -> Option<NaiveDateTime> {
        let ts = self.mtime();
        Local.timestamp_opt(ts, 0).single().map(|dt| dt.naive_local())
    }

    pub fn md5(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_md5(&content);
            }
        }
        "".to_string()
    }

    pub fn sha1(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_sha1(&content);
            }
        }
        "".to_string()
    }

    pub fn sha256(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_sha256(&content);
            }
        }
        "".to_string()
    }

    pub fn sha512(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_sha512(&content);
            }
        }
        "".to_string()
    }

    pub fn mime_type(&self) -> String {
        if self.is_dir() {
            return "inode/directory".to_string();
        }
        let ext = self.ext().to_lowercase();
        match ext.as_str() {
            "txt" | "md" | "cfg" | "conf" | "sh" | "rs" | "py" | "c" | "cpp" | "h" | "hpp" | "java" | "go" | "js" | "ts" | "json" | "toml" | "yaml" | "yml" | "xml" | "html" | "css" => {
                "text/plain".to_string()
            },
            "png" => "image/png".to_string(),
            "jpg" | "jpeg" => "image/jpeg".to_string(),
            "gif" => "image/gif".to_string(),
            "svg" => "image/svg+xml".to_string(),
            "pdf" => "application/pdf".to_string(),
            "zip" => "application/zip".to_string(),
            "gz" | "gzip" => "application/gzip".to_string(),
            "tar" => "application/x-tar".to_string(),
            "mp3" => "audio/mpeg".to_string(),
            "wav" => "audio/wav".to_string(),
            "mp4" => "video/mp4".to_string(),
            "mkv" => "video/x-matroska".to_string(),
            _ => "application/octet-stream".to_string(),
        }
    }
}
EOF"}

