        self.path.extension()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| "".to_string())
    }

    pub fn relative_path_string(&self) -> String {
        if let Some(prefix) = &self.archive_prefix {
            let rel = self.path.to_string_lossy().to_string();
            format!("{} {}", prefix, rel)
        } else {
            let s = self.path.to_string_lossy().to_string();
            if s.starts_with("./") {
                s[2..].to_string()
            } else {
                s
            }
        }
    }

    pub fn abspath_string(&self) -> String {
        let abs = if self.full_path.is_absolute() {
            self.full_path.clone()
        } else {
            std::env::current_dir().unwrap_or_default().join(&self.full_path)
        };
        let abs_str = abs.to_string_lossy().to_string();

        if let Some(prefix) = &self.archive_prefix {
            format!("{} {}", prefix, self.path.to_string_lossy())
        } else {
            abs_str
        }
    }

    pub fn dir_string(&self) -> String {
        self.path.parent()
            .map(|p| {
                let s = p.to_string_lossy().to_string();
                if s.starts_with("./") {
                    s[2..].to_string()
                } else {
                    s
                }
            })
            .unwrap_or_else(|| "".to_string())
    }

    pub fn absdir_string(&self) -> String {
        let abs = if self.full_path.is_absolute() {
            self.full_path.clone()
        } else {
            std::env::current_dir().unwrap_or_default().join(&self.full_path)
        };
        abs.parent()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|| "".to_string())
    }

    pub fn size(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.len()).unwrap_or(0)
    }

    pub fn is_dir(&self) -> bool {
        self.metadata.as_ref().map(|m| m.is_dir()).unwrap_or(false)
    }

    pub fn is_file(&self) -> bool {
        self.metadata.as_ref().map(|m| m.is_file()).unwrap_or(false)
    }

    pub fn is_symlink(&self) -> bool {
        self.metadata.as_ref().map(|m| m.file_type().is_symlink()).unwrap_or(false)
    }

    pub fn is_pipe(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0x1000).unwrap_or(false)
    }

    pub fn is_char(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0x2000).unwrap_or(false)
    }

    pub fn is_block(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0x6000).unwrap_or(false)
    }

    pub fn is_socket(&self) -> bool {
        self.metadata.as_ref().map(|m| (m.mode() & 0xF000) == 0xC000).unwrap_or(false)
    }

    pub fn is_hidden(&self) -> bool {
        self.name().starts_with('.')
    }

    pub fn is_empty(&self) -> bool {
        if self.is_dir() {
            fs::read_dir(&self.full_path).map(|mut d| d.next().is_none()).unwrap_or(true)
        } else {
            self.size() == 0
        }
    }

    pub fn is_shebang(&self) -> bool {
        if self.is_file() && self.size() >= 2 {
            if let Ok(data) = fs::read(&self.full_path) {
                return data.starts_with(b"#!");
            }
        }
        false
    }

    pub fn is_binary(&self) -> bool {
        let mime = self.mime_type();
        !mime.starts_with("text/") && mime != "application/json" && mime != "application/javascript" && mime != "application/xml"
    }

    pub fn is_text(&self) -> bool {
        !self.is_binary()
    }

    pub fn mode_bits(&self) -> u32 {
        self.metadata.as_ref().map(|m| m.mode()).unwrap_or(0)
    }

    pub fn mode_string(&self) -> String {
        format_mode_unix(self.mode_bits(), self.is_dir(), self.is_symlink())
    }

    pub fn uid(&self) -> u32 {
        self.metadata.as_ref().map(|m| m.uid()).unwrap_or(0)
    }

    pub fn gid(&self) -> u32 {
        self.metadata.as_ref().map(|m| m.gid()).unwrap_or(0)
    }

    pub fn user_name(&self) -> String {
        nix::unistd::User::from_uid(nix::unistd::Uid::from_raw(self.uid()))
            .ok()
            .flatten()
            .map(|u| u.name)
            .unwrap_or_else(|| self.uid().to_string())
    }

    pub fn group_name(&self) -> String {
        nix::unistd::Group::from_gid(nix::unistd::Gid::from_raw(self.gid()))
            .ok()
            .flatten()
            .map(|g| g.name)
            .unwrap_or_else(|| self.gid().to_string())
    }

    pub fn device(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.dev()).unwrap_or(0)
    }

    pub fn rdev(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.rdev()).unwrap_or(0)
    }

    pub fn inode(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.ino()).unwrap_or(0)
    }

    pub fn blocks(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.blocks()).unwrap_or(0)
    }

    pub fn nlink(&self) -> u64 {
        self.metadata.as_ref().map(|m| m.nlink()).unwrap_or(1)
    }

    pub fn atime(&self) -> i64 {
        self.metadata.as_ref().map(|m| m.atime()).unwrap_or(0)
    }

    pub fn mtime(&self) -> i64 {
        self.metadata.as_ref().map(|m| m.mtime()).unwrap_or(0)
    }

    pub fn ctime(&self) -> i64 {
        self.metadata.as_ref().map(|m| m.ctime()).unwrap_or(0)
    }

    pub fn created_datetime(&self) -> Option<NaiveDateTime> {
        self.metadata.as_ref()
            .and_then(|m| m.created().ok())
            .map(|t| {
                let dt: DateTime<Local> = DateTime::from(t);
                dt.naive_local()
            })
    }

    pub fn accessed_datetime(&self) -> Option<NaiveDateTime> {
        let ts = self.atime();
        Local.timestamp_opt(ts, 0).single().map(|dt| dt.naive_local())
    }

    pub fn modified_datetime(&self) -> Option<NaiveDateTime> {
        let ts = self.mtime();
        Local.timestamp_opt(ts, 0).single().map(|dt| dt.naive_local())
    }

    pub fn md5(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_md5(&content);
            }
        }
        "".to_string()
    }

    pub fn sha1(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_sha1(&content);
            }
        }
        "".to_string()
    }

    pub fn sha256(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_sha256(&content);
            }
        }
        "".to_string()
    }

    pub fn sha512(&self) -> String {
        if self.is_file() {
            if let Ok(content) = fs::read(&self.full_path) {
                return hashes::calc_sha512(&content);
            }
        }
        "".to_string()
    }

    pub fn mime_type(&self) -> String {
        if self.is_dir() {
            return "inode/directory".to_string();
        }
        let ext = self.ext().to_lowercase();
        match ext.as_str() {
            "txt" | "md" | "cfg" | "conf" | "sh" | "rs" | "py" | "c" | "cpp" | "h" | "hpp" | "java" | "go" | "js" | "ts" | "json" | "toml" | "yaml" | "yml" | "xml" | "html" | "css" => {
                "text/plain".to_string()
            },
            "png" => "image/png".to_string(),
            "jpg" | "jpeg" => "image/jpeg".to_string(),
            "gif" => "image/gif".to_string(),
            "svg" => "image/svg+xml".to_string(),
            "pdf" => "application/pdf".to_string(),
            "zip" => "application/zip".to_string(),
            "gz" | "gzip" => "application/gzip".to_string(),
            "tar" => "application/x-tar".to_string(),
            "mp3" => "audio/mpeg".to_string(),
            "wav" => "audio/wav".to_string(),
            "mp4" => "video/mp4".to_string(),
            "mkv" => "video/x-matroska".to_string(),
            _ => "application/octet-stream".to_string(),
        }
    }
}
EOF"}

{"command":"cat <<'EOF' > src/traversal.rs
use std::fs;
use std::path::PathBuf;
use ignore::WalkBuilder;

use crate::ast::SearchRoot;
use crate::config::Config;
use crate::file_info::FileInfo;
use crate::zip_search::search_zip_archive;

pub struct TraversalResult {
    pub files: Vec<FileInfo>,
    pub errors: Vec<String>,
}

pub fn traverse_root(root: &SearchRoot, config: &Config) -> TraversalResult {
    let mut files = Vec::new();
    let mut errors = Vec::new();

    let root_path = PathBuf::from(&root.path);

    let use_gitignore = root.gitignore.unwrap_or(config.gitignore.unwrap_or(false));

    let mut builder = WalkBuilder::new(&root_path);
    builder.hidden(false);
    builder.git_ignore(use_gitignore);
    builder.git_global(use_gitignore);
    builder.git_exclude(use_gitignore);
    builder.follow_links(root.symlinks);

    if let Some(max_d) = root.max_depth {
        builder.max_depth(Some(max_d));
    }
    if let Some(min_d) = root.min_depth {
        builder.min_depth(Some(min_d));
    }

    let mut entries = Vec::new();
    for result in builder.build() {
        match result {
            Ok(entry) => {
                let p = entry.path().to_path_buf();
                if p == root_path && root.min_depth.unwrap_or(1) >= 1 {
                    continue;
                }
                let meta = entry.metadata().ok();

                let rel_path = match p.strip_prefix(&root_path) {
                    Ok(r) => r.to_path_buf(),
                    Err(_) => p.clone(),
                };

                let full_p = match fs::canonicalize(&p) {
                    Ok(cp) => cp,
                    Err(_) => p.clone(),
                };

                let fi = FileInfo {
                    path: rel_path,
                    full_path: full_p,
                    _root_path: root_path.clone(),
                    archive_prefix: None,
                    _is_archive_entry: false,
                    metadata: meta,
                };

                entries.push(fi);
            }
            Err(err) => {
                errors.push(err.to_string());
            }
        }
    }

    if root.dfs {
        files.extend(entries);
    } else {
        entries.sort_by(|a, b| {
            let depth_a = a.path.components().count();
            let depth_b = b.path.components().count();
            if depth_a != depth_b {
                depth_a.cmp(&depth_b)
            } else {
                a.path.cmp(&b.path)
            }
        });
        files.extend(entries);
    }

    if root.archives {
        let mut archive_files = Vec::new();
        for fi in &files {
            if fi.is_file() {
                let ext = fi.ext();
                if config.is_ext_match(&ext, "zip_archive") {
                    let zip_entries = search_zip_archive(&fi.full_path, &fi.path, &root_path);
                    archive_files.extend(zip_entries);
                }
            }
        }
        files.extend(archive_files);
    }

    TraversalResult { files, errors }
}
EOF"}

