{"command":"cat <<'EOF' > src/interactive.rs
use std::io::{self, Write};
use std::env;

use crate::cli::{execute_query_string, print_help_text};
use crate::config::Config;

pub fn run_interactive_mode(config: Config, enable_color: bool) {
    let mut show_errors = true;
    let stdin = io::stdin();
    let is_terminal = unsafe { libc::isatty(libc::STDIN_FILENO) == 1 };

    loop {
        if is_terminal {
            print!("query> ");
            io::stdout().flush().ok();
        }

        let mut line = String::new();
        if stdin.read_line(&mut line).is_err() || line.is_empty() {
            break;
        }

        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        let lower = trimmed.to_lowercase();
        if lower == "exit" || lower == "quit" {
            break;
        } else if lower == "pwd" {
            if let Ok(p) = env::current_dir() {
                println!("{}", p.to_string_lossy());
            }
        } else if lower.starts_with("cd ") || lower == "cd" {
            let path = trimmed[2..].trim();
            if path.is_empty() {
                if let Some(home) = dirs::home_dir() {
                    env::set_current_dir(home).ok();
                }
            } else {
                if let Err(e) = env::set_current_dir(path) {
                    if show_errors {
                        eprintln!("{}: {}", path, e);
                    }
                }
            }
        } else if lower.starts_with("errors") {
            let parts: Vec<&str> = trimmed.split_whitespace().collect();
            if parts.len() > 1 && parts[1].eq_ignore_ascii_case("off") {
                show_errors = false;
                println!("Errors are OFF");
            } else {
                show_errors = true;
                println!("Errors are ON");
            }
        } else if lower == "help" {
            print_help_text(enable_color);
        } else {
            execute_query_string(trimmed, &config, enable_color, show_errors);
        }
    }
}
EOF"}

