{"command":"cat <<'EOF' > src/lexer.rs
#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    Keyword(String),
    Identifier(String),
    StringLiteral(String),
    Integer(i64),
    Float(f64),
    SizeLiteral(u64),
    Operator(String),
    Comma,
    LParen,
    RParen,
    LBrace,
    RBrace,
    Eof,
}

pub struct Lexer {
    chars: Vec<char>,
    pos: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            chars: input.chars().collect(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        if self.pos < self.chars.len() {
            Some(self.chars[self.pos])
        } else {
            None
        }
    }

    fn advance(&mut self) -> Option<char> {
        if self.pos < self.chars.len() {
            let ch = self.chars[self.pos];
            self.pos += 1;
            Some(ch)
        } else {
            None
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.peek() {
            if ch.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    pub fn tokenize(&mut self) -> Result<Vec<Token>, String> {
        let mut tokens = Vec::new();
        loop {
            self.skip_whitespace();
            let ch = match self.peek() {
                Some(c) => c,
                None => {
                    tokens.push(Token::Eof);
                    break;
                }
            };

            match ch {
                ',' => {
                    self.advance();
                    tokens.push(Token::Comma);
                }
                '(' => {
                    self.advance();
                    tokens.push(Token::LParen);
                }
                ')' => {
                    self.advance();
                    tokens.push(Token::RParen);
                }
                '{' => {
                    self.advance();
                    tokens.push(Token::LBrace);
                }
                '}' => {
                    self.advance();
                    tokens.push(Token::RBrace);
                }
                '\'' | '"' | '`' => {
                    let quote = self.advance().unwrap();
                    let mut s = String::new();
                    let mut escaped = false;
                    let mut closed = false;
                    while let Some(c) = self.advance() {
                        if escaped {
                            s.push(c);
                            escaped = false;
                        } else if c == '\\' {
                            escaped = true;
                        } else if c == quote {
                            closed = true;
                            break;
                        } else {
                            s.push(c);
                        }
                    }
                    if !closed && quote != '`' {
                        return Err("Unterminated string literal".to_string());
                    }
                    tokens.push(Token::StringLiteral(s));
                }
                '=' | '!' | '<' | '>' | '~' | '+' | '-' | '*' | '/' | '%' => {
                    let mut op = String::new();
                    op.push(self.advance().unwrap());
                    while let Some(c) = self.peek() {
                        if matches!(c, '=' | '~' | '>') {
                            op.push(self.advance().unwrap());
                        } else {
                            break;
                        }
                    }
                    tokens.push(Token::Operator(op));
                }
                _ if ch.is_ascii_digit() => {
                    let mut num_str = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() || c == '.' {
                            num_str.push(self.advance().unwrap());
                        } else {
                            break;
                        }
                    }
                    let mut suffix = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_alphabetic() {
                            suffix.push(self.advance().unwrap());
                        } else {
                            break;
                        }
                    }

                    if !suffix.is_empty() {
                        let mult = match suffix.to_lowercase().as_str() {
                            "b" => 1,
                            "k" | "kb" | "kib" => 1024,
                            "m" | "mb" | "mib" => 1024 * 1024,
                            "g" | "gb" | "gib" => 1024 * 1024 * 1024,
                            "t" | "tb" | "tib" => 1024u64 * 1024 * 1024 * 1024,
                            "p" | "pb" | "pib" => 1024u64 * 1024 * 1024 * 1024 * 1024,
                            _ => 0,
                        };
                        if mult > 0 {
                            let n: f64 = num_str.parse().unwrap_or(0.0);
                            tokens.push(Token::SizeLiteral((n * mult as f64) as u64));
                        } else {
                            let full = format!("{}{}", num_str, suffix);
                            tokens.push(Token::Identifier(full));
                        }
                    } else if num_str.contains('.') {
                        if let Ok(f) = num_str.parse::<f64>() {
                            tokens.push(Token::Float(f));
                        } else {
                            tokens.push(Token::Identifier(num_str));
                        }
                    } else {
                        if let Ok(i) = num_str.parse::<i64>() {
                            tokens.push(Token::Integer(i));
                        } else {
                            tokens.push(Token::Identifier(num_str));
                        }
                    }
                }
                _ if ch.is_alphanumeric() || ch == '_' || ch == '.' || ch == '/' || ch == '\\' || ch == '*' || ch == '?' || ch == ':' => {
                    let mut word = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_alphanumeric() || matches!(c, '_' | '.' | '/' | '\\' | '*' | '?' | ':' | '-') {
                            word.push(self.advance().unwrap());
                        } else {
                            break;
                        }
                    }

                    let upper = word.to_uppercase();
                    match upper.as_str() {
                        "SELECT" | "FROM" | "WHERE" | "GROUP" | "BY" | "ORDER" | "ASC" | "DESC" |
                        "LIMIT" | "OFFSET" | "INTO" | "AND" | "OR" | "NOT" | "BETWEEN" | "IN" |
                        "EXISTS" | "AS" | "MINDEPTH" | "MAXDEPTH" | "DEPTH" | "ARCHIVES" | "ARC" |
                        "SYMLINKS" | "SYM" | "GITIGNORE" | "GIT" | "NOGITIGNORE" | "NOGIT" |
                        "HGIGNORE" | "HG" | "NOHGIGNORE" | "NOHG" | "DOCKERIGNORE" | "DOCKER" |
                        "NODOCKERIGNORE" | "NODOCKER" | "DFS" | "BFS" | "IS" => {
                            tokens.push(Token::Keyword(upper));
                        }
                        "EQ" => tokens.push(Token::Operator("=".to_string())),
                        "EEQ" => tokens.push(Token::Operator("===".to_string())),
                        "NE" => tokens.push(Token::Operator("!=".to_string())),
                        "ENE" => tokens.push(Token::Operator("!==".to_string())),
                        "LT" => tokens.push(Token::Operator("<".to_string())),
                        "LTE" | "LE" => tokens.push(Token::Operator("<=".to_string())),
                        "GT" => tokens.push(Token::Operator(">".to_string())),
                        "GTE" | "GE" => tokens.push(Token::Operator(">=".to_string())),
                        "RX" | "REGEXP" => tokens.push(Token::Operator("=~".to_string())),
                        "NOTRX" => tokens.push(Token::Operator("!=~".to_string())),
                        "LIKE" => tokens.push(Token::Operator("LIKE".to_string())),
                        "NOTLIKE" => tokens.push(Token::Operator("NOTLIKE".to_string())),
                        "PLUS" => tokens.push(Token::Operator("+".to_string())),
                        "MINUS" => tokens.push(Token::Operator("-".to_string())),
                        "MUL" => tokens.push(Token::Operator("*".to_string())),
                        "DIV" => tokens.push(Token::Operator("/".to_string())),
                        "MOD" => tokens.push(Token::Operator("%".to_string())),
                        _ => {
                            tokens.push(Token::Identifier(word));
                        }
                    }
                }
                _ => {
                    let unknown = self.advance().unwrap();
                    tokens.push(Token::Identifier(unknown.to_string()));
                }
            }
        }
        Ok(tokens)
    }
}
EOF"}

